// Frozen edition decisions; never modify collected metadata.
export const aestheticsEditions = [{"source_id":"scholarvox:88951506","title":"Acteurs et architectes","authors":["Collectif"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9791037001948","9791037023193"],"description":"Architecture et cinéma auront été dès l'origine enchaînés l'un à l'autre. Chaplin, Lang, Vidor, Truffaut, Resnais revêtirent des habits d'architecte, car le plus proche parent du cinéma est l'architecture, la machine cinématographique ne pouvant se passer d'architecture et simultanément en démontrant la puissance. Il n'y a pas de cinéma sans architecture, sans porte à claquer ni escalier à dévaler, sans terrasse où promener sa solitude, sans fenêtre, sans balcon. Le cinéma démontre à quoi sert l'architecture, ce que nous devrions savoir de ce qui s'y peut produire. Réciproquement, la bonne architecture est celle qui a choisi le cinéma, elle fait scène avant le cinéma, elle s'invente comme scénario et scénographie, la promenade architecturale qui débouche sur l'horizon de l'océan Pacifique. L'architecture comme le cinéma transforme chaque sujet en acteur.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":1,"bookId":"book-7daaf0314e7795f49b76"},{"source_id":"openedition:enseditions--22305","title":"Américônes","authors":["Marc Chénetier"],"publisher":"ENS Éditions","platform":"openedition","isbns":["9782902126347","9791036203558"],"description":"Ces six essais sur l’image aux États-Unis examinent la peinture, la photographie et le cinéma américains. De la présentation panoramique à l’examen méticuleux d’une ou plusieurs œuvres, ils mettent en rapport la culture d’un pays soupçonneux des icônes avec le contexte historique, idéologique, esthétique qui les a vus naître. L’accent est mis sur la méthodologie de la lecture d’image. À rebours des idées reçues, ces textes résultent des travaux présentés par les équipes de recherche « Clinamens » de l’École Normale Supérieure de Fontenay/Saint-Cloud au cours de l’année 1995-1996 et constituent un outil de travail utile à tous ceux que passionne l’iconographie.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":2,"bookId":"book-ba0ab7bbfd0921b9e35e"},{"source_id":"openedition:edizionikaplan--2210","title":"Antologia critica della videoarte italiana 2010-2020","authors":["Piero Deggiovanni"],"publisher":"Edizioni Kaplan","platform":"openedition","isbns":["9788899559359","9788899559465"],"description":"Presentando una selezione dei principali autori della videoarte italiana – quelli che, a nostro avviso, hanno contribuito in modo originale allo sviluppo del linguaggio video in questo Paese negli ultimi dieci anni – questo libro si propone di rilanciare la questione metodologica relativa alla videoarte facendo ritornare questa forma espressiva nell’alveo che le è proprio: l’arte contemporanea. Esistono numerosissimi studi sui decenni trascorsi e anche una sorta di nostalgia per l’epoca dello sperimentalismo sui mezzi che fa parlare di rinascita analogica o di neo sperimentalismo, riconducendolo però nell’ambito del linguaggio cinematografico, ma la videoarte è propriamente Arte e non Cinema. Riportandola nel suo ambito originario, crediamo di poter dimostrare che essa si è ritagliata lo spazio autonomo necessario per continuare a esistere, accanto ad altre forme audiovisive, come genere a sé stante, che muta a partire dall’evoluzione dei mezzi e integra nelle proprie opere elementi eterogenei che possono provenire da molteplici ambiti, dal cinema alla poesia visiva, all’animazione, al teatro, senza alcuna sudditanza nei confronti di queste altre discipline. Questo processo, del tutto inedito, passa sotto il nome d’ibridazione.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":3,"bookId":"book-0fd4aa0424f1d7509efa"},{"source_id":"scholarvox:88951535","title":"Archaïsme et impureté : Les écarts de Pasolini, Paradjanov et Oliveira","authors":["Letoulat, Alice"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9791037006509","9791037006516"],"description":"Cet ouvrage a pour ambition d'analyser la posture esthétique marginale qu'adoptent trois cinéastes rarement étudiés conjointement, l'Italien Pier Paolo Pasolini (1922-1975), le soviétique Sergueï Paradjanov (1924-1990) et le Portugais Manoel de Oliveira (1908-2015). Chez eux, les gestes filmiques marquent une volonté d'échapper aux limites encadrant conventionnellement le cinéma et les thématiques qu'il aborde. Ainsi, ces films à l'ambivalence revendiquée se situent à l'écart des formes dominantes et ouvrent une voie détournée privilégiant les choix archaïsants et impurs. Ceux-ci témoignent d'un ethos cinématographique dont on étudie la portée tant esthétique que politique. Trois gestes constitutifs de ce décalage sont identifiés. Tout d'abord, l'acte de fonder se manifeste dans les images filmiques par de nombreux motifs archéologiques ; la quête d'origines garantit la constitution d'un monde à habiter et dans lequel circuler. C'est ce deuxième geste de circulation qui occupe la suite de l'analyse : les films étudiés mettent en jeu d'importants réseaux d'emprunt et de redistribution qui montrent combien l'enracinement originel ne s'accompagne pas nécessairement de l'érection de délimitations rigides, pensées au contraire ici comme poreuses. Ce choix répété du débordement constitue ainsi la troisième et dernière partie de cet ouvrage : dans ces films, la spécificité cinématographique ainsi que les corps et jusqu'aux temps eux-mêmes débordent leur cadrage conventionnel.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":4,"bookId":"book-c1f097b84919f726b202"},{"source_id":"openedition:pur--307810","title":"Biopouvoir en culture de l'écran","authors":[],"publisher":"Presses universitaires de Rennes","platform":"openedition","isbns":["9791041300617","9791041311156"],"description":"La notion de biopouvoir définie par Foucault comme le contrôle de la vie par une forme de pouvoir souvent (mais pas seulement) incarnée par l’État, a fait preuve de sa pertinence lors de la pandémie de COVID-19. Cet ouvrage analyse plus particulièrement les formes multiples du biopouvoir, les résistances et les adhésions qu’il peut susciter. Il tente de comprendre leur mise en œuvre dans la culture de l’écran telle que vécue par nos sociétés contemporaines. Littératures anglophones et productions télévisuelles, de Margaret Atwood à Don DeLillo, de Desperate Housewives à Westworld, côtoient ainsi des analyses des systèmes de gestion d’épidémie, de reconnaissance faciale, et des figures tutélaires de la fiction comme le monstre ou le zombie. Le livre permet de réfléchir aux formes du biopouvoir, dans ses manifestations corporelles, sociales, numériques, et culturelles, à la fois sous l’angle de la discipline et de la biopolitique.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéma et société"]},"reason":"Biopouvoir, corps social, frontieres, savants representes, publics, precarite, ville, migrations ou critique amateur : angle social principal.","index":5,"bookId":"book-baf35096314a53e5b184"},{"source_id":"scholarvox:88977282","title":"Cavell's Ontology of Film : The World Viewed After Half a Century","authors":["Gerrits, Jeroen"],"publisher":"Anthem Press","platform":"scholarvox","isbns":["9781839995149","9781839995156"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":6,"bookId":"book-104ff4551864c9748a12"},{"source_id":"scholarvox:88806994","title":"Cinéma","authors":["Faure, Elie"],"publisher":"Manucius","platform":"scholarvox","isbns":["9782845781153","9782845782914"],"description":"Élie Faure (1873-1937) médecin, historien, essayiste, est surtout connu pour sa monumentale\nHistoire de l'art\nen sept tomes (1909-1927). Mais il était aussi attentif au devenir prochain de notre civilisation qu'il voyait entrer sous l'emprise définitive de la machine, destin qu'il ne déplorait pas, bien au contraire, il y saisissait l'aurore d'un nouveau cycle civilisationnel - fin de l'individualisme et entrée dans un modèle plus collectif dont la machine fournira le modèle et les moyens - et dont le cinéma pourrait en devenir l'art emblématique de par sa proximité native avec la machine et de par le caractère essentiellement massif de sa diffusion. Il fut l'auteur du premier grand article théorique sur le septième art en 1920 : \"De la cinéplastique\".\nSes écrits sur le cinéma, bien connus des cinéphiles et abondamment cités dans la littérature spécialisée, sont disséminés dans l'ensemble de ses textes.\nIls furent partiellement réunis, seize ans après sa mort, en 1953, sous le titre\nFonction du cinéma\n, aux éditions Plon, puis réédités (revus et augmentés) par les éditions Gonthiers, \"Bibliothèque Médiations\", sous le même titre en 1964. Depuis l'épuisement de cette dernière édition, les écrits sur le cinéma d'Élie Faure n'étaient plus disponibles, sauf pour\nDe la cinéplastique\n, paru aux éditions Séguier en 1993.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":7,"bookId":"book-eb313b02eed276889aa8"},{"source_id":"scholarvox:88916009","title":"Cinéma : Les Grands Articles d'Universalis","authors":["Encyclopaedia Universalis"],"publisher":"Encyclopaedia Universalis","platform":"scholarvox","isbns":["9782341006354"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinématographie"]},"reason":"Synthese generale, histoire des mouvements et cinematographies; reference/parodie encyclopedique pour Anticyclopedie, pas traite conceptuel.","index":8,"bookId":"book-a0f3484f850e123cb55a"},{"source_id":"scholarvox:88862996","title":"Cinéma critique : Adorno, de Francfort à Hollywood","authors":["Moquin-Beaudry, Ludvic","Macdonald, Iain"],"publisher":"Groupe Nota Bene","platform":"scholarvox","isbns":["9782895185574","9782895185581"],"description":"La position d'Adorno à l'égard du cinéma a souvent été assimilée à un rejet total, motivé par une conception élitiste, voire bourgeoise, qui refuse de considérer pertinente la participation du septième art à l'effort d'émancipation humaine. Premier livre en langue française portant spécifiquement sur le cinéma chez Adorno, le présent essai s'efforce plutôt de montrer que la pensée adornienne nous incite à trouver un intéressant juste milieu entre deux positions également excessives : le mépris catégorique de la culture populaire, qui ferme les yeux sur ses facettes les plus fécondes, et le regard ébahi et rampant porté sur cette culture, qui nourrissait les esprits à l'époque d'Adorno et alimente aujourd'hui les travaux d'un nombre croissant de philosophes, d'écrivains et de chercheurs.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":9,"bookId":"book-27085cb19a0a7fe3f4f0"},{"source_id":"openedition:septentrion--38948","title":"Cinéma et imaginaire baroque","authors":["Emmanuel Plasseraud"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757400234","9782757421178"],"description":"Le style baroque, défini dans un premier temps par Aloïs Riegl et Heinrich Wölfflin à partir de l'art du 17e siècle, est devenu un concept qui s'est élargi au-delà de ses frontières initiales, si bien que l'on a pu l'appliquer, par exemple, au cinéma, art du 20e siècle. En effet, parce qu'il est un dispositif de projection d'ombres, d'artifices, d'illusions, de mise en mouvement des images, le cinéma semble correspondre au désir profond du baroque de dépasser la représentation réaliste du monde pour accéder à la dimension de l'imaginaire. Mais cette utilisation du concept de baroque au cinéma ne va pas de soi, et tout l'enjeu de ce livre, qui vient après des tentatives éparses et parfois contradictoires, est d'offrir une présentation synthétique d'un cinéma baroque qui est envisagé sous l'angle de sa métaphysique illusionniste et de sa physique de l'infiniment divers.\n\tIl s'agit donc de proposer une théorie du cinéma au regard du baroque, à partir d'analyses d'œuvres de cinéastes qui se sont dits influencés par ce style, comme Raoul Ruiz, Peter Greenaway ou Emir Kusturica. C'est aussi l'occasion de relire les films de réalisateurs reconnus, comme Orson Welles, Federico Fellini, Max Ophuls, Alain Resnais ou David Lynch et de découvrir des cinéastes plus marginaux, comme Kenneth Anger, Jos Stelling, Alejandro Jodorowsky, Wojciech Has ou Carmelo Bene.\n\tPour ces cinéastes, le baroque n'est pas qu'un style du passé. Il est un miroir qui permet surtout de penser notre monde moderne, et d'offrir au cinéma des possibilités de renouvellement formel laissant espérer, pour l'avenir, de riches perspectives de développements.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":10,"bookId":"book-9951735ec1bd563381f3"},{"source_id":"openedition:ugaeditions--39858","title":"Cinéma et imaginaire topographique","authors":["Fabien Meynier"],"publisher":"UGA Éditions","platform":"openedition","isbns":["9782377473175","9782377474080"],"description":"Définir les contours d’un « imaginaire topographique » qui préside aux modalités de descriptions de lieux au sein d’une multitude de productions culturelles : telle est l’ambition de cet ouvrage. À travers l’analyse de trois œuvres considérées comme des jalons dans le développement de cet imaginaire, celles de John Ford, de Jean-Marie Straub et Danièle Huillet et de Tariq Teguia, l’objectif est de saisir la façon dont les cinéastes s’inscrivent dans certaines traditions iconographiques liées aux représentations topographiques, tout en inventant de nouvelles images des lieux qu’ils enregistrent. La prise en compte de ces lieux ainsi que de la longue durée dans les analyses de films permet de porter un regard nouveau sur des œuvres déjà connues et de saisir leurs relations avec des films plus contemporains, à travers un problème d’image spécifique, celui de l’invention de lieux proprement filmiques.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":11,"bookId":"book-b56bb37b954f92b658a4"},{"source_id":"scholarvox:41001244","title":"Cinéma et inconscient","authors":["Gagnebin, Murielle"],"publisher":"Editions Champ Vallon","platform":"scholarvox","isbns":["9782876733367","9782876737921"],"description":"Cinema et inconscient - Murielle Gagnebin","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":12,"bookId":"book-09d0a33400fe2d7c48df"},{"source_id":"scholarvox:88921763","title":"Cinéma et peinture : Passages, partages, présences","authors":["Vancheri, Luc"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200254919","9782200352844"],"description":"Un débat ouvert dès la naissance du cinéma.. La nouveauté de cet ouvrage relève : . d’une part de sa triple mise en perspective esthétique, historique et théorique, laquelle entend restaurer leur caractère lié. . d’autre part, de sa faculté à faire entendre, tout en l’analysant, le fait que le cinéma est bien plus : ¬ que l’invention séparée d’une nouvelle technique de production et de projection des images, ¬ qu’un nouveau régime d’images et de fiction ; ¬ qu’ un simple renouvellement des conditions spectatorielles. C ’est cela qui a permis l’institution du cinéma comme art dès lors qu’il devenait identifiable aux conceptions de l’art héritées de la peinture. Le cinéma a rejoué en peu de temps ce que la peinture avait mis plusieurs siècles, dès le milieu du 17e, a instruire pour elle-même. De nombreux exemples développés viennent appuyer l’argumentation.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":13,"bookId":"book-b1ca06a90f0e9622a0e2"},{"source_id":"scholarvox:88969589","title":"Cinéma muséum - Le musée d'après le cinéma","authors":["Lemaître, Barbara","Verraes, Jennifer"],"publisher":"Presses Universitaires de Vincennes","platform":"scholarvox","isbns":["9782842923723","9782842924683"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":14,"bookId":"book-03678b545d4039d2c679"},{"source_id":"scholarvox:88960318","title":"Cinéma ou réalité ? : Entre perception et mémoire","authors":["Sibony, Daniel"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9791037039682","9791037039699"],"description":"Il y a des films que l'on reçoit comme une simple vague d'images. Et il y en a qui provoquent des effets de retour, sans doute parce qu'ils butent en nous sur des fonds cachés. Le retour, c'est ce qui ramène des choses enfouies ou inconnues, par des effets de miroir, de double, de spectre ou de revenant.Le retour amène une autre réalité, qui vient s'appliquer sur celle qui est déjà-là, faisant du film un entre-deux-réalités. L'œuvre est alors comme dédoublée.C'est ce rapport dialectique entre le cinéma et la réalité, qui fait que le cinéma venge le rêve, que le présent essai entend interroger.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":15,"bookId":"book-71db398817dc2a0022a0"},{"source_id":"openedition:enseditions--11061","title":"Cinéma, Numérique, Survie","authors":["Jean-Louis Comolli"],"publisher":"ENS Éditions","platform":"openedition","isbns":["9791036201059","9791036201073"],"description":"Qu’est-ce qui dresse le cinéma contre les accélérations du tout numérique ? Les aurores après la tempête ne se voient plus que sur les écrans des salles de cinéma. Numérisés, les capitaux et les catastrophes détruisent le monde des matins tranquilles. La guerre est dans le temps. C’est à la chaîne que le numérique fabrique du virtuel, du mirage, de la monnaie de singe. En ce monde-hologramme, il n’est plus ni corps ni chair, les mains ne caressent plus rien, les blessures elles-mêmes sont factices. Cette nuée d’images nous dérobe le réel et peu à peu impose le désert des hommes et des choses. Contre la violence des exils, la salle de projection n’est-elle pas la dernière demeure de l’humain ? Face à la démultiplication des écrans, l’hypervisibilité, la transparence, comment le cinéma peut-il encore préserver sa part d’ombre et rester une arme critique ? Jusqu’où la révolution numérique n’est-elle pas en train d’affecter l’expérience esthétique et morale du cinéma, et au-delà, notre civilisation ?","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":16,"bookId":"book-da68bf1864a0dd93e478"},{"source_id":"scholarvox:88948903","title":"Contemporary Art, World Cinema, and Visual Culture : Essays by Hamid Dabashi","authors":["Keshmirshekan, Hamid"],"publisher":"Anthem Press","platform":"scholarvox","isbns":["9781783089192","9781783089208"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":17,"bookId":"book-f388581e14f73841a48c"},{"source_id":"openedition:septentrion--134271","title":"Continuité et discontinuité au cinéma","authors":["Esther Jacopin"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757437100","9782757437131"],"description":"Qu’est-ce que la continuité ? À la lumière de son expérience de scripte cinéma, l’auteure analyse l’organisation spatio-temporelle des divers éléments qui constituent un film de fiction afin d’identifier les mécanismes à l’œuvre pour assurer sa compréhension par les spectateurs. Des écrits de Georges Méliès à ceux de Maurice Merleau-Ponty, la définition de la continuité est enrichie par une approche transdisciplinaire, mettant en correspondance le cinéma avec les sciences, la philosophie, la musique et l’architecture pour définir les caractéristiques d’une continuité dite apparente. Cette définition sert dans un second temps de grille d’analyse pour étudier l’histoire et l’esthétique de la stéréoscopie au cinéma, du fonctionnement de la vision binoculaire humaine jusqu’aux productions contemporaines. Cette étude a servi de socle à la réalisation de deux courts métrages en 3Ds, fruits d’un travail de recherche-création visant à dessiner les contours d’une continuité stéréoscopique.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":18,"bookId":"book-2756d93fa66170d64f69"},{"source_id":"scholarvox:88927303","title":"De Charcot à Charlot : Mises en scène du corps pathologique","authors":["Gordon, Rae Beth"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753522503","9782753561618"],"description":"De Charcot à Charlot : Mises en scène du corps pathologique, publié en anglais en 2001, est le premier livre à proposer une analogie entre le spectacle populaire et l'hystérie à l'hôpital dans le dernier tiers du XIXe siècle. Il met en lumière un rapport direct entre la gestuelle des hystériques et celle des artistes du café-concert et du cinéma burlesque. Chanteurs et comiques s'emparent du langage corporel de l'hystérie avec ses mouvements saccadés, automatiques et convulsifs, rehaussés de tics et grimaces, pour inventer un nouveau répertoire gestuel. De nouveaux genres sont créés : le Chanteur Agité, le Comique Idiot ou encore la Chanteuse Épileptique (dont Mistinguett). Les symptômes psychopathologiques sont ainsi à la source d'une esthétique nouvelle, perçue comme l'incarnation de la modernité. Les premiers films comiques français reprennent ce répertoire de mouvement frénétique. Il s'agit d'un moment culturel en France où l'imprégnation de la culture populaire par le savoir médical est exceptionnelle, vulgarisé par maints articles sur l'hystérie et l'hypnose dans la presse. Le livre s'attache aussi – et c'est une deuxième contribution majeure – à repérer et analyser les réactions physiologiques des spectateurs. Dès 1880, les expériences en psychophysiologie sur les phénomènes d'imitation démontrent en effet que la simple vue d'un mouvement chez autrui donne lieu à l'ébauche du même mouvement chez le spectateur (ce que confirmera la découverte récente des « neurones-miroirs »). Explorant les ramifications de cette imitation inconsciente chez les spectateurs autour de 1900, l'auteure propose ainsi une nouvelle théorie de la réception du spectacle par le public, tant au café-concert que dans les numéros de magnétiseurs et dans les premiers films burlesques.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéma et société"]},"reason":"Biopouvoir, corps social, frontieres, savants representes, publics, precarite, ville, migrations ou critique amateur : angle social principal.","index":19,"bookId":"book-5ca602a1fd39c013f5f0"},{"source_id":"scholarvox:88805639","title":"Dickens & Griffith : Genèse du gros plan","authors":["Eisenstein, Sergueï Mikhaïlovitch"],"publisher":"Stalker éditeur","platform":"scholarvox","isbns":["9782952671941"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":20,"bookId":"book-4dea7efbbce91311b85c"},{"source_id":"openedition:pul--47328","title":"Dictionnaire d'iconologie filmique","authors":["Vancheri Luc"],"publisher":"Presses universitaires de Lyon","platform":"openedition","isbns":["9782729713751","9782729713768"],"description":"Alors qu’au xvie siècle l’iconologie est considérée comme un discours sur les images destiné à l’usage des peintres, elle se réinvente au cours du xixe siècle, sous l’impulsion des historiens de l’art, comme une technique d’interprétation des œuvres. Aby Warburg y verra l’instrument privilégié d’une « science de la culture ». Conçu par des chercheurs issus d’horizons disciplinaires différents et organisé autour de cinq catégories réparties en une centaine d’entrées – les théoriciens de l’art et du cinéma, les cinéastes, les films, les notions et les motifs –, ce dictionnaire entend tout à la fois reformuler l’iconologie au cinéma et répondre d’une histoire élargie des images. De Walter Benjamin à Jacques Rancière, d’Arnaud Desplechin à Tsai Ming-liang, du Cuirassé Potemkine à Shining et du burlesque au zombie, les contributions proposées constituent un outil et une source de réflexion aujourd’hui indispensables à tous ceux qui font de l’analyse un accès privilégié à la connaissance des films.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":21,"bookId":"book-2a572fafd82a90aefe18"},{"source_id":"scholarvox:88921832","title":"Dictionnaire théorique et critique du cinéma","authors":["Aumont, Jacques","Marie, Michel"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200601218","9782200617004"],"description":"Le cinéma est devenu, depuis près d'un demi-siècle, objet d'enseignement, de recherches et d'études. Un vocabulaire particulier s'est progressivement imposé, constitué à la fois de termes spécifiques et de concepts nouveaux propres à analyser le langage cinématographique.D'Abstrait à Zombi, ce dictionnaire réunit près de 600 entrées relevant des approches théoriques et critiques du cinéma : notions clés en esthétique, filmologie, sémiotique… ainsi que notices sur les critiques et les théoriciens, parfois aussi cinéastes (Eisenstein, Hitchcock, Pasolini, Godard…), qui ont contribué à enrichir la réflexion sur le 7e art. Chaque entrée est replacée dans son contexte, illustrée d'exemples, mise en relation avec d'autres et suivie d'indications bibliographiques. Cette 3e édition s'enrichit d'une centaine d'articles, faisant le point sur l'état des lieux (économique, technique, critique…) et éclairant l'œuvre de toute une génération de théoriciens.Un outil indispensable pour l'étudiant en cinéma et audiovisuel, le professionnel ou le cinéphile soucieux de mieux connaître son domaine de prédilection.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":22,"bookId":"book-817ab114d422f26ff741"},{"source_id":"openedition:septentrion--106130","title":"Doublures du visible","authors":["Jacques Aumont"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757432877","9782757433232"],"description":"Le rôle historique du cinéma est de nous avoir donné le visible une seconde fois, en ajoutant le temps à l’image. Il reste pourtant dans tout film une large part d’invisible : c’est elle qui est ici décrite, et explorée.\n\tLe cinéma en effet nous rend conscients de l’ambiguïté fondamentale de notre relation au visible. Sa force documentaire, comme son jeu inné avec la fiction, lui ont permis de convoquer les invisibles essentiels du monde, et aussi bien, des effets psychiques qui mettent en péril la visibilité du visible. Il nous autorise à croire que nous voyons vraiment quelque chose d’autre que le monde des apparences.\n\tCe livre ne fait ni la théorie, ni l’histoire de cette doublure du visible que transporte le cinéma, mais en donne un panorama complet, attentif à ne jamais trancher abstraitement, mais à toujours s’appuyer sur des exemples concrets, et nombreux.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":23,"bookId":"book-d7deab5fb6fefe554e70"},{"source_id":"openedition:pus--36728","title":"Du noir dont procèdent les figures","authors":[],"publisher":"Presses universitaires de Strasbourg","platform":"openedition","isbns":["9791034401574","9791034403578"],"description":"Qu’il s’agisse du noir en tant que couleur, matériau, support ou geste technique, cet ouvrage s’attache à explorer les utilisations et les enjeux esthétiques du noir au cinéma. De ce point de vue, l’ouvrage entend renouveler des approches du cinéma exclusivement construites autour de la couleur, faisant du noir non seulement l’attribut d’objets filmés, mais aussi un milieu ou bien une conduite créatrice. S’interroger sur la manière dont on « fait le noir » au cinéma invite à embrasser une large étendue d’objets filmiques, courant du film de fiction au film expérimental, et du film en prises de vue réelles au film d’animation. L’ouvrage réunit des chercheurs inscrits dans les domaines de l’histoire et de l’esthétique du cinéma, des arts plastiques et de la théorie de l’art.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":24,"bookId":"book-8331705ff24d559a10c9"},{"source_id":"scholarvox:88951771","title":"Du parti pris des lieux dans le cinéma contemporain : Akerman, Alonso, Costa, Dumont, Huillet & Straub, Mograbi, Tarr…","authors":["Maury, Corinne"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9782705695293","9791037011152"],"description":"Que\npeut\nle lieu\nau cinéma, lorsqu’il n’est pas limité à être le décor de l’action, ni même confondu avec le paysage, encore moins réduit à un espace à parcourir ou encore amalgamé à une espèce de neutralité territoriale ? Des cinéastes tels que Chantal Akerman, Lisandro Alonso, Pedro Costa, Bruno Dumont, Béla Tarr, Avi Mograbi, Tariq Teguia, Philippe Grandrieux, Danièle Huillet & Jean-Marie Straub ou encore Sharunas Bartas choisissent de ne pas (con)centrer exclusivement la narration cinématographique sur la seule trajectoire des personnages. Les lieux qu’ils figurent à l’écran sont des spatialités telluriques, des territoires d’habitation, des matrices existentielles où se mobilisent des manières de faire et de vivre, où s’accomplissent tant des forces d’émancipation que des adynamies existentielles. Cellule d’accueil, pivot remarquable, refuge de trajectoires individuelles et communautaires, le lieu au cinéma rayonne tantôt comme un chantier précaire, tantôt comme une fortification inébranlable.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":25,"bookId":"book-2d15c3389e48f4df0306"},{"source_id":"scholarvox:88951772","title":"Du postmodernisme au posthumanisme : Littérature et cinéma, Europe - États-Unis - Amérique latine","authors":["Collectif"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9791037013378","9791037015419"],"description":"Si des travaux sur le posthumanisme ont vu le jour depuis son entrée dans le champ philosophique dans les dernières années du xxe siècle, leur développement actuel doit tenir compte non seulement de l'évolution du concept et des avancées technoscientifiques récentes, mais également des réponses et des réactions que son apparition a provoquées.Cet ouvrage propose d'abord une définition du posthumanisme comme un système de discours, cherchant ainsi à rendre compte de la multiplicité des perspectives qu'il ouvre, des implications pour les réflexions et représentations littéraires et cinématographiques, et des positionnements politiques, parfois radicalement opposés, qu'il suscite.Sont ensuite présentées douze recherches, centrées sur trois aires géographiques et culturelles : la première partie porte sur l'Europe et les États-Unis ; dans la deuxième, pour la première fois, sont étudiés les discours du posthumanisme dans l'Amérique latine. Dans les deux cas, il s'agit de considérer le posthumanisme comme un outil épistémologique et de l'examiner, après le postmodernisme, comme une possible épistémè contemporaine.Avec les contributions de : Marie Baudoin, Hugo Clémot, Amaury Dehoux, Marie-Laure Delaporte, Louise Ibanez-Drillières, Laurène Sanchez, Barnabé Sauvage, Apolline Taillandier, Carlos Tello, Carlos Tous.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":26,"bookId":"book-ffb5d9f08d63629f8a2e"},{"source_id":"openedition:puc--16030","title":"Edgar Morin et le cinéma","authors":["Vignaux Valerie"],"publisher":"Presses universitaires de Caen","platform":"openedition","isbns":["9782381850160","9782381852072"],"description":"Edgar Morin aura consacré au cinéma deux décennies de recherche, de 1945 à 1965, une période qui peut sembler de courte durée à l’aune de son importante carrière mais qui peut aussi être considérée comme fondamentale puisqu’elle se situe à l’origine de sa pensée. Ses activités sont alors partagées entre réflexions théoriques, avec la parution de deux livres majeurs : Le cinéma ou l’homme imaginaire (1956) et Les stars (1957), et expériences de réalisation cinématographique, avec Chronique d’un été (1961), un film qui l’associe à Jean Rouch et qui révolutionna le cinéma documentaire. L’ouvrage interroge la singularité de ses propositions en restituant les contextes intellectuels et épistémologiques à partir desquels il a développé son projet d’anthropologie sociologique. Et l’étude de Chronique d’un été permet d’observer à travers les dispositifs les implications du geste filmé dans sa capacité à révéler l’être au monde. Autant de réflexions qui restituent l’importance et la singularité des propositions cinématographiques de Morin, retrouvant de la sorte la dimension politique du voir et du savoir.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":27,"bookId":"book-aa964aa26f6f821e9f11"},{"source_id":"openedition:pur--74780","title":"Enchantements désenchantés","authors":["Anne E. Duggan"],"publisher":"Presses universitaires de Rennes","platform":"openedition","isbns":["9782753541221","9782753561465"],"description":"L’intérêt du public n’a jamais faibli pour Jacques Demy, un des cinéastes les plus singuliers de la Nouvelle Vague, auteur entre autres de Lola, Les Parapluies de Cherbourg, Les Demoiselles de Rochefort, Peau d’Âne et Une chambre en ville. Aucune monographie nouvelle, pourtant, ne lui a été consacrée en France depuis plus de vingt ans, comme s’il ne devait être l’objet que des somptueux livres d’images qui se sont multipliés sur sa vie et son œuvre.\n\n\tL’étude finement détaillée de l’universitaire américaine Anne E. Duggan vient combler ce manque et stimuler la réflexion en s’attachant principalement à cinq films analysés en profondeur (aussi bien Lola, Les Parapluies de Cherbourg et Peau d’Âne que les moins connus The Pied Piper et Lady Oscar) pendant que d’autres films du cinéaste sont évoqués plus rapidement. L’approche théorique d’Anne Duggan rompt radicalement avec le consensus critique établi autour de l’œuvre de Demy, puisqu’elle choisit de se placer dans le double éclairage des études sur le conte (dont elle retrouve les archétypes jusque dans Lola et dans Les Parapluies de Cherbourg) et des queer studies qui, dans la continuation des gender studies, cherchent à identifier une pratique artistique fondée sur le refus des marges et des frontières.\n\n\tLe livre d’Anne Duggan est une contribution majeure au renouvellement du discours critique sur Demy. C’est aussi un superbe hommage à la complexité d’une œuvre cinématographique dont on ne se lasse pas d’explorer les faces les plus secrètes.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéastes"]},"reason":"Monographie Jacques Demy et etude de Michelangelo Frammartino; pas theorie generale du medium.","index":28,"bookId":"book-522f09494e8ede51b5a8"},{"source_id":"openedition:puv--158","title":"Entre film et photographie","authors":["Barbara Le Maître"],"publisher":"Presses universitaires de Vincennes","platform":"openedition","isbns":["9782842921569","9782842929077"],"description":"Approche psychanalytique du croisement cinéma/photographie : revenir sur l'empreinte lumineuse à partir de l'empreinte psychique, en explorant le lien établi par Freud entre le manque, le désir et l'empreinte.\n\n\tÀ l'origine de ce livre, il y a d'abord le trouble éprouvé chaque fois qu'une photographie apparaît au sein d'un film : qu'ont à faire ensemble ces images dans l'élaboration figurative ? Et surtout quel rapport entretiennent-elles avec l'empreinte sur le fond primordial de laquelle elles s'enlèvent l'une et l'autre ? Au moment où il élabore sa mécanique du désir, Freud pose un lien singulier entre le manque, l'empreinte et l'image : pas de désir sans manque, dit-il en substance, et surtout pas de désir sans empreinte et sans transformation de l'empreinte en image. L'enjeu consiste alors à revenir sur l'empreinte lumineuse à partir de l'empreinte psychique : faisant l'hypothèse que le manque est une force constitutive du travail des images-empreintes, on montrera comment l'irruption du photographique au sein du filmique nous renvoie face au premier laboratoire du désir.\n\n\tPrincipaux films de référence : Les Vacances du cinéaste (Johan Van der Keuken), Calendar (Atom Egoyan), Les Photos d'Alix (Jean Eustache).","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":29,"bookId":"book-3c997a399620fce67c7b"},{"source_id":"scholarvox:88921825","title":"Esthétique du film : 125 ans de théorie et de cinéma","authors":["Aumont, Jacques","Bergala, Alain","Marie, Michel"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200630010","9782200631581"],"description":"Ce livre s'appuie sur l'histoire de l'art, la narratologie, la sémiologie et la psychanalyse, ainsi que sur de multiples exemples de films, pour présenter l'essentiel des aspects théoriques et esthétiques du cinéma. L'ouvrage s'articule autour de cinq questions, développées en détail à travers cinq chapitres : la perception et la forme, le récit, la signification, le dispositif et le spectateur, l'art. Dans un dernier chapitre, une réflexion plus prospective sur le numérique rappelle que nous vivons une ère hautement évolutive.Paru initialement en 1983, ce volume résolument interdisciplinaire a été, pour des générations d'étudiants, l'un des « classiques » des études cinématographiques. Remettant l'ouvrage sur le métier une quarantaine d'années plus tard, les quatre auteurs, théoriciens attentifs à la réalité sociale et vivante du cinéma, l'ont enrichi afin que cette 5e édition d'Esthétique du film prenne en compte les changements survenus, tant dans le cinéma lui-même que dans son étude. Une référence fondamentale toujours indispensable aujourd'hui.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":30,"bookId":"book-d8ff6993ca9b94a5e199"},{"source_id":"scholarvox:88927301","title":"Fictions d’images : Essai sur l'attribution de propriétés fictives aux images de films","authors":["Siety, Emmanuel"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753507623","9782753527065"],"description":"Il fut un temps où l'on se plaisait à attribuer aux images des pouvoirs merveilleux on imaginait qu'elles étaient vivantes, ou qu'on pouvait y entrer comme dans un autre monde; on leur attribuait toutes sortes de propriétés fictives, en les sachant fictives. L'image n'était pas alors uniquement le site d'une fiction, mais une fiction en elle-même. Ce temps est toujours le nôtre. Cet ouvrage propose d'examiner la façon dont le cinéma, avec les pouvoirs optiques et sonores qui sont les siens, active cette tendance fondamentale de l'être humain à attribuer aux images des propriétés fictives. Cette tendance ne se manifeste pas uniquement au travers de récits filmiques. Elle informe, beaucoup plus profondément qu'on ne le croit, notre expérience de spectateurs ordinaires de cinéma. Et elle est pour l'historien et l'analyste d'images assez sages (c'est-à-dire suffisamment déraisonnables) pour ne pas rompre avec leur imagination, une source essentielle de découverte.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":31,"bookId":"book-67dc7d2d3a379c78a415"},{"source_id":"openedition:puv--7998","title":"Figuration de l’inhumain","authors":["Luc Vancheri"],"publisher":"Presses universitaires de Vincennes","platform":"openedition","isbns":["9782379241260","9782903981839"],"description":"Cet essai s’organise autour de quelques objets choisis dans le cinéma américain, relevant tous de la figuration humaine et mettant en jeu le corps de l’homme.\n\n\tÀ travers des films de Cecil B. DeMille, Don Siegel, Keaton et Preminger, il s’agit d’étudier comment l’homme filmique, dessaisi de soi par les variations de la syntaxe figurative, se trouve relégué au rôle de motif iconographique, jouxtant de près le décor au point de s’y confondre : devenir accessoire de l’homme, où se donne à voir l’avènement de la figurine, soit une image de l’inhumain.\n\n\tReprendre le problème de la représentation au cinéma c’est ainsi revenir à une hypothèse critique, qui pourrait rendre concevable un Autre de la figure.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":32,"bookId":"book-467fc359f517528d7d4c"},{"source_id":"scholarvox:88927300","title":"Figures de l'écrivain dans le cinéma américain : Itinéraires de la voix baladeuse","authors":["Bolter, Trudy"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753526860","9782868476180"],"description":"L’écrivain-personnage est un pôle d’attraction tant pour le cinéaste que pour le spectateur : Hollywood a produit plus de 250 films traitant d’écrivains. Mais pourquoi reviennent-ils donc si souvent dans le cinéma américain ? Trudy Bolter, Américaine, maître de conférences en culture nord-américaine à l’Institut d’études politiques de Bordeaux (université Montesquieu Bordeaux 4), analyse une vingtaine de « writer-films » pour expliquer le pouvoir de la figure de l’écrivain sur la scène culturelle des États-Unis. À travers la mise en spectacle de l’écrivain-personnage, oscillant entre sanctification et déchéance, le spectateur qui « réécrit » l’histoire du film met en marche sa « voix baladeuse », se reconnaissant dans le personnage. Grâce à l’étude de l’histoire culturelle des États-Unis et à l’analyse textuelle, guidée par la psychologie cognitive bordwellienne et le formalisme russe eichenbaumien, Trudy Bolter décrit et définit la « voix baladeuse » où s’exprime l’envie d’écrire présente chez le spectateur.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":33,"bookId":"book-11e8b787199c53a5f0db"},{"source_id":"scholarvox:88915179","title":"Figures du clown, sur scène, en piste et à l'écran","authors":["Goudard, Philippe","Vienne-Guerrin, Nathalie"],"publisher":"Presses universitaires de la Méditerranée","platform":"scholarvox","isbns":["9782367813325","9782367813684"],"description":"Aux questions légitimes qui se posent sur le clown et auxquelles cet ouvrage est consacré, les plus fameux artistes du genre comme Charles Chaplin, Charlie Rivel ou Dimitri ont euxmêmes répondu avec une fulgurance qui intimide. Les clowns ne sont pas des rigolos ! C'est donc avec l'humilité de rigueur devant l'ampleur de la tâche - le clown est un objet d'étude complexe et le champ à explorer immense - que les directeurs de ce volume ont abordé cette réflexion sur les Figures du clown, sur scène, en piste et à l'écran.\nL'ouvrage invite de nombreux spécialistes, scientifiques et artistes à explorer la figure clownesque selon différentes thématiques qui constituent les six chapitres de ce volume : le clown élisabéthain, les femmes clowns, le clown au tournant du xxe siècle, ses grandes figures, sa face tragique et enfin, la question du rire. Ainsi, cette approche anthologique autant que kaléidoscopique, contribuera à l'actualisation des connaissances sur la figure clownesque. Du moins ose-t-on le croire, même avertis par W. C. Fields : « Tout le monde a besoin de croire en quelque chose. Moi, je crois que je vais reprendre une bière. »","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Genres"]},"reason":"Etude transversale de la figure comique du clown entre scene, piste et ecran; acces hors cinema preserves.","index":34,"bookId":"book-a463f4f7fb4d66e953d5"},{"source_id":"scholarvox:88927299","title":"Filmer l'acte de création","authors":["Frangne, Pierre-Henry","Viart, Christophe","Mouëllic, Gilles"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753507838","9782753527034"],"description":"Que dit le cinéma - documentaire ou de fiction - sur la naissance des œuvres, qu’elles soient celles des autres arts ou les siennes propres ? Pourquoi et en quels sens le cinéma est-il un instrument privilégié et fécond d’observation, d’analyse et d’interprétation de la genèse des œuvres d’art ? Que nous apprend le cinéma sur la relation du créateur à son œuvre et sur les opérations de la création que celle-ci soit entendue comme l’acte par lequel une œuvre d’art est instaurée comme nouvelle et significative, ou qu’elle soit pensée comme la première manifestation publique d’une œuvre d’art quand elle doit d’être représentée ou exécutée ? Telles sont les principales questions de cet ouvrage. La création n’y sera pas abandonnée à son mystère, à sa fulgurance ou à sa généralité. Au contraire, elle sera approchée au plus près des œuvres, des artistes, des gestes et des processus.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":35,"bookId":"book-55c154838148bdc1ffa1"},{"source_id":"scholarvox:88927298","title":"Filmer l'artiste au travail","authors":["le Forestier, Laurent","Mouëllic, Gilles"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753522824","9782753561601"],"description":"Le rapport entre le cinéma et les autres arts a suscité un nombre considérable d'écrits, inaugurés par les premières tentatives pour définir le cinéma comme un art, fondées notamment sur des comparaisons avec la peinture et la musique. Les textes qui constituent cet essai se situent donc dans la continuité d'une histoire déjà longue, avec cependant le parti pris affirmé de prendre quelques distances avec d'une part cette dimension comparatiste et d'autre part l'affirmation du cinéma comme possible « synthèse des arts » ou manifestation d'une mythique « œuvre d'art totale ». Plus modestement, ces contributions proposent d'analyser des rencontres possibles entre le cinéma et la création artistique en prenant comme entrée les séquences de fictions ou de documentaires qui tentent de montrer l'artiste au travail. Cette approche très ouverte permet de parcourir l'histoire du cinéma, des danses serpentines des premiers temps aux autoportraits de Jean-Luc Godard, Agnès Varda ou Alain Cavalier, des critofilms de Carlo L. Ragghianti aux mises en abyme complexes d'Abbas Kiarostami ou de Nuri Bilge Ceylan, tout en mêlant dans un même mouvement de pensée des films dont le projet est de donner à voir la genèse d'une œuvre picturale (La Belle Noiseuse de Jacques Rivette) ou théâtrale (Elvire Jouvet 40 de Brigitte Jaques et Benoît Jacquot) et des films où la création est envisagée de façon moins frontale ou plus métaphorique, telles les figures d'écrivains en panne d'inspiration dans les films de Wim Wenders ou encore la confusion entre acteurs et personnages dans les performances de Louis Jouvet et Sacha Guitry, « monstres sacrés » du cinéma français. Une telle pluralité de propositions n'aurait guère de sens si elle n'était envisagée dans un projet de recherche fermement bâti autour d'une étude des potentialités du cinéma à démythifier l'acte de création en considérant l'œuvre non comme une réalité achevée mais comme un processus. Chacune des études présentées dans cet ouvrage travaille ainsi une tension entre le geste créateur comme recherche incertaine et une hypothèse selon laquelle toute œuvre garde la trace des conditions de son élaboration.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":36,"bookId":"book-c4f78d74d41a4a9e9d5d"},{"source_id":"scholarvox:88912753","title":"Filmer le quotidien","authors":["Moure, José","Chateau, Dominique","Leperchey, Sarah"],"publisher":"Les Impressions nouvelles","platform":"scholarvox","isbns":["9782874497247","9782874497278"],"description":"Si le cinéma a une influence si déterminante sur nos modes de vie, c?est sans doute parce qu?il a toujours su fournir des réponses précieuses à qui se demande comment les gens vivent. Explorant des univers filmiques très différents - des films de fiction aux films documentaires, du cinéma d?auteur aux comédies contemporaines hollywoodiennes, des films de symphonies urbaines aux documentaires intimistes, des œuvres de Yasujiro Ozu à celles de Chantal Akerman, d?Alain Resnais à Jim Jarmusch, de Maurice Pialat à Wang Bing? -, ce livre se propose d?ouvrir un questionnement non seulement sur ce que le cinéma peut nous dire du quotidien, mais aussi sur la façon dont il l?appréhende, le donne à voir et parfois le réinvente.00Comment filmer ce qui, d?ordinaire, n?est plus perçu ? Comment faire de la vie de tous les jours, de ce qui ne fait pas événement et ne mérite pas d?être montré, l?enjeu d?un regard singulier, d?un mode de narration et représentation propre, tout simplement d?une attention cinématographique particulière.0.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":37,"bookId":"book-943d9f2d39620381fad0"},{"source_id":"scholarvox:88969653","title":"Filmer les frontières","authors":["Maury (Dir.), Corinne","Ragel (Dir.), Philippe"],"publisher":"Presses Universitaires de Vincennes","platform":"scholarvox","isbns":["9782842924591","9782842924614"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéma et société"]},"reason":"Biopouvoir, corps social, frontieres, savants representes, publics, precarite, ville, migrations ou critique amateur : angle social principal.","index":38,"bookId":"book-837d3746269792056a4b"},{"source_id":"openedition:septentrion--112968","title":"Filmer l’éphémère","authors":["Pascal Bouchez"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757434819","9782859399795"],"description":"Peut-on filmer le théâtre ?\n\tPourquoi, pour qui, et comment ?\n\tAutant de questions décisives abordées ici sous des angles variés à l’heure ou la multiplication et la démocratisation des technologies ne font qu’accroître la demande de contenus et de programmes. Après avoir examiné en détail les potentialités et les contraintes des traces de « captation » et de « recréation », l’auteur propose une solution originale de multicaptation documentaire, fondée sur un dispositif contextualisé d’enregistrements multiples et différenciés de l’éventail des représentations publiques d’un spectacle. Cela dans une dialogique de contribution significative à la réflexion contemporaine sur l’élaboration d’une mémoire précise et créative du théâtre, et de trace « spectaculaire » à même de répondre aux attentes immédiates du grand public.\n\tCet ouvrage s’adresse aussi bien au chercheur et à l’étudiant en Arts du spectacle et en audiovisuel qu’aux praticiens de ces deux disciplines, en passant par un public curieux de la « fabrication » d’une œuvre théâtrale, en l’occurrence ici celle de Daniel Mesguich. Il s’adresse également à celui qui souhaite mieux comprendre un vécu professionnel lié à des pratiques audiovisuelles dans l’univers du spectacle vivant.\n\tChemin faisant, cette compréhension s’articule dans un double mouvement de réflexion pour agir sur le terrain, et d’intégration d’un recul critique de cette action. En cela, l’auteur redonne vie à une aventure humaine intense, celle qui lui a permis d’oeuvrer en tant que réalisateur à la création en 1991 du premier pôle vidéo intégré dans une structure théâtrale en France.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Réalisation"]},"reason":"Multicaptation documentaire du theatre; recits journalistiques de tournages, corrobores chez Capricci.","index":39,"bookId":"book-763a6bbe420c8b271499"},{"source_id":"scholarvox:88904455","title":"Fonction du cinéma","authors":["Faure, Elie"],"publisher":"République des Lettres","platform":"scholarvox","isbns":["9782824902692"],"description":"Texte inrégral révisé suivi d'une biographie d'Élie Faure. Élie Faure a aimé Charlie Chaplin dès son premier film. Mêlé aux aux foules anonymes du début du cinéma, il a vibré comme il fallait, ri quand il le fallait, comme tout le monde. Critique d'art clairvoyant et conscient de sa satisfaction, il fut aussi l'un des premiers esthéticiens à célébrer l'art du cinéma et en a tiré des conclusions qui n'ont pas été sans déterminer son attitude devant l'évolution générale de notre civilisation. Voici, reconstitué par une série d'essais extraits de ses œuvres, son témoignage prophétique, majeur et toujours d'actualité, sur le septième art. Comparant le cinéma à la peinture, à la danse, au théâtre, à l'architecture, à la musique, l'auteur de la célèbre \"\nHistoire de l'Art\n\" en marque la destination profonde, à la fois rythmique et plastique. Il y aborde notamment \"La prescience du Tintoret\", \"La danse et le cinéma\", \"La cinéplastique\", \"Charlot\", \"La mystique du cinéma\", \"La vocation du cinéma\", et enfin une \"Défense et illustration de la machine\" dont le cinéma serait l'art emblématique.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":40,"bookId":"book-df84387b33190eeeeff4"},{"source_id":"openedition:ledizioni--502","title":"Formula e metafora","authors":[],"publisher":"Ledizioni","platform":"openedition","isbns":["9788867052073","9788867053568"],"description":"In un frammento pubblicato il 10 dicembre 1810 nei suoi «Berliner Abendblätter», Heinrich von Kleist sosteneva che “gli uomini si potrebbero dividere in due categorie: quelli che si intendono di metafore e quelli che si intendono di formule”. A due secoli di distanza, questo volume prende a prestito la coppia kleistiana “formula e metafora” per indagare le sorti dello scienziato come personaggio nelle letterature e culture di una contemporaneità intesa nel senso più ampio possibile.\n\n\tLo scienziato – benefattore o criminale, saggio o irresponsabile, opportunista o pazzo, freddo calcolatore o debole strumento del potere, personaggio comico o tragico, drammatico o grottesco – è uno dei protagonisti della cultura contemporanea. Che si tratti di personalità storiche o di figure d’invenzione, alimentate da prototipi letterari e da stereotipi di varia matrice, uomini di scienza popolano le più varie opere di finzione da fine Ottocento a oggi: il volume ne indaga ventisei esempi, spaziando fra letteratura, teatro e cinema nei mondi di lingua francese, inglese, italiana, polacca, russa, spagnola, svedese e tedesca. Le molteplici declinazioni del personaggio-scienziato sono lo specchio più o meno deformato di eventi e problemi che hanno alimentato l’inesausto interrogarsi dell’intellettuale moderno sul rapporto fra scienza, arte e società. Al contempo, esse rivelano nelle loro radici il perdurare di antiche e moderne figurazioni mitologico-letterarie, trasformate da scrittori e artisti per interpretare consapevolmente il passato e il presente.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéma et société"]},"reason":"Biopouvoir, corps social, frontieres, savants representes, publics, precarite, ville, migrations ou critique amateur : angle social principal.","index":41,"bookId":"book-260ab5e7e120154b97d3"},{"source_id":"openedition:res--693","title":"Fotogrammi dal moderno","authors":["Antonio Tricomi"],"publisher":"Rosenberg & Sellier","platform":"openedition","isbns":["9788878853768","9788878854338"],"description":"Hitchcock, Welles e Lang; Huston, Kubrick e Laughton. L’espressionismo, il noir e il western; Leni Riefenstahl, Germi e Altman. Il neorealismo e il poliziottesco italiani; Bellocchio, Haneke e Sokurov. Il cinema hollywoodiano dei nostri anni e i giochi di prestigio di Christopher Nolan. In Fotogrammi dal moderno, l’autore fa dialogare questi e altri maestri, queste e altre poetiche cinematografiche, con sicuri capisaldi del pensiero contemporaneo, con svariate opere letterarie, per sondare il rapporto tra tali mondi stilistici e i contesti storico-sociali che li hanno visti nascere o di cui essi hanno inteso offrirci acute trasfigurazioni. L’esegesi filmica si traduce così, pagina dopo pagina, nell’irrinunciabile tassello di una più ampia riflessione critica sul Novecento, sull’oggi.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":42,"bookId":"book-724ba9d59b236502b82b"},{"source_id":"peterlang:1306696","title":"Gemeinsam/Together II","authors":[],"publisher":"Peter Lang","platform":"peterlang","isbns":["9783631897256","9783631897263"],"description":"How do people with and without disabilities work together in the artistic process? This volume is a compilation of 14 interviews with directors and producers of European feature films that enriches the understanding of interabled dynamics in creative ventures. It highlights the work of actors with learning disabilities, along with, behind the scenes knowledge of the casting process, training methods, brainstorming sessions to incorporate their inputs, production process, unforeseen challenges that they encounter on sets and the critical and audience reception of the film. It is also an attempt to explore if such films could be categorised as belonging to the ‘inclusive films’ genre. The volume concludes with reflections on the limits and possibilities of artistic expression offered by theatre and films to the people with learning disabilities.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Jeu d’acteur"]},"reason":"Entretiens sur creation interhandicap, acteurs, casting et formation, pas theorie generale.","index":43,"bookId":"book-83fab369666dbe02d75e"},{"source_id":"openedition:edizionikaplan--95","title":"Il cinema che serve","authors":["Federica Villa"],"publisher":"Edizioni Kaplan","platform":"openedition","isbns":["9788889908518","9788889908921"],"description":"Questo libro nasce dal desiderio di ripercorrere un decennio di vita del cinema italiano, gli anni Cinquanta che, stretti tra il neorealismo e la modernità degli anni Sessanta, appaiono, a ogni rinnovato studio, un campo prezioso di esercizio per trascorrere dal vecchio al nuovo, dalla tradizione a forme rinnovate per il nostro cinema. E studiando questo periodo si incontra Giorgio Bassani come uomo di cinema. Un aspetto, questo, sicuramente minore rispetto alla mai abbastanza celebrata personalità di fine letterato e di indomito intellettuale. Ma un aspetto che ci permette di rileggere il cinema di quegli anni come grande momento di elaborazione di un passato prossimo, di un’eredità cogente, di una storia appena trascorsa, ma anche come volano per intraprendere spericolate strade divergenti, rotte alternative che puntano a un orizzonte che appena si intravede. Seguire le tracce lasciate dalla relazione di Bassani con il cinema italiano significa, dunque, prendere le mosse da una biografia, dalla storia di una vita, e ritornare sentimentalmente a un periodo che ha visto letterati impegnati a fianco di personalità del mondo del cinema tentare la bella impresa del confronto, animati dall’idea di fondare una nuova forma di scrittura intermedia e contemporanea.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinématographie"]},"reason":"Synthese generale, histoire des mouvements et cinematographies; reference/parodie encyclopedique pour Anticyclopedie, pas traite conceptuel.","index":44,"bookId":"book-73a511594fd4ec7f51c7"},{"source_id":"openedition:edizionikaplan--2050","title":"Il destino impresso","authors":["Bruno Surace"],"publisher":"Edizioni Kaplan","platform":"openedition","isbns":["9788899559441","9788899559472"],"description":"Esiste un nesso fra i film che guardiamo e il modo in cui diamo senso a noi stessi e al nostro abitare il mondo? In che modo le storie sul grande schermo ci aiutano a rifuggire l’horror vacui? Se il cinema veicola un’idea di destino, se guardando i film ci rimane un destino impresso, si possono pensare dei metodi per capire come effettivamente si attua un procedimento tanto delicato ed essenziale? Attraverso una metodologia sfaccettata, che integra semiotica, film philosophy e storia del cinema, questo volume prova a rispondere a simili domande, accompagnandoci in un vertiginoso viaggio attraverso centinaia di film, dal cinema delle origini a quello contemporaneo, dal cinema d’autore al b-movie, dal cartone animato al documentario, delineando le basi per una teoria della destinalità nel cinema.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":45,"bookId":"book-aa678fe826c56b690459"},{"source_id":"openedition:enseditions--9081","title":"Images des corps / Corps des images au cinéma","authors":["Jérôme Game"],"publisher":"ENS Éditions","platform":"openedition","isbns":["9782847882124","9791036200489"],"description":"Ces dernières années ont vu se développer un important effort théorique et critique sur la question du corps au cinéma : comment ce dernier représente-t-il les formes du corps mais aussi ses puissances (gestes, désirs, pulsions, tendances hors cadre, hors champs, hors discours ou hors normes) ? Comment rend-il compte des contextes cognitifs, culturels, politiques et technologiques associés à – ou affectés par – la fabrique des corps à travers l’histoire ? Les films eux-mêmes ont eu recours au corps comme figure ou motif privilégié et ont pleinement participé de ce questionnement. Contribuant à cette réflexion en cours le présent volume s’attache à étudier la question de la représentation corporelle en la rapportant à celle des devenirs concrets du cinéma, que ce soit dans ses dispositifs propres ou ses rencontres avec d’autres régimes d’image (notamment la vidéo et la photographie). L’ambition est en définitive d’offrir une sorte d’état des lieux de la question qui rayonnerait dans plusieurs directions : mise à l’épreuve des concepts ; articulation entre perspectives théoriques ; poétique des oeuvres ; zoom sur certains points clés du rapport corps/image (la question de la vitesse notamment) ; enjeux culturels, politiques, esthétique et de genre ; question du récit, etc. C’est sur ces théâtres que se déploient les études réunies ici, chacune avec sa méthodologie et ses objets propres mais toutes envisageant la notion élargie de corps-image (au sens d’une matériologie générale du cinéma) comme possible paradigme critique.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":46,"bookId":"book-8b39e04a75cd0f423da4"},{"source_id":"openedition:pum--10746","title":"Images et sociétés","authors":["Catherine Saouter"],"publisher":"Presses de l’Université de Montréal","platform":"openedition","isbns":["9782760618688","9791036502514"],"description":"Comme l'eau, comme le gaz, comme le courant électrique viennent de loin, dans nos demeures, répondre à nos besoins moyennant un effort quasi nul, ainsi serons-nous alimentés d'images visuelles et auditives, naissant et s'évanouissant au moindre geste, presque à un signe.\n\n\tPaul Valéry, 1934","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Photographie"},"reason":"Catherine Saouter : photographie documentaire, medias et ideologie, pas theorie specifique du cinema; corroboration du resume editorial.","index":47,"bookId":"book-c133ff488852cf2d4382"},{"source_id":"scholarvox:88952000","title":"Imaginaires du déjà-vu : Resnais, Rivette, Lynch et les autres","authors":["Arnaud, Diane"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9782705693190","9791037015433"],"description":"Au cinéma, l'art du déjà-vu crée des effets de remémoration et de reconnaissance encore plus troublants que dans nos vies. Vertigo d'Alfred Hitchcock et La Jetée de Chris Marker ont montré la voie : ressusciter une histoire d'amour, revoir une scène marquante. Les films mystérieux d'Alain Resnais, de Jacques Rivette, de David Lynch sont au cœur du livre, car ils confrontent avec une ingéniosité inouïe la compulsion de répétition au désir de recréation. De L'Année dernière à Marienbad, Je t'aime, je t'aime et Providence à Céline et Julie vont en bateau, L'Amour par terre et Histoire de Marie et Julien en passant par Lost Highway, Mulholland Drive ou Inland Empire, les moments inquiétants, amusants parfois, où le spectateur perçoit des plans et des situations déjà vus l'amènent à se déplacer sur les scènes du souvenir, du rêve, du fantasme. Ces formes originales de déjà-vu font accéder aux possibilités imaginaires de la réinvention pour échapper à un destin tout tracé.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":48,"bookId":"book-0baa06ca7d3f42c2f3e4"},{"source_id":"openedition:pressesinalco--111","title":"KinoFabula","authors":["Catherine Géry"],"publisher":"Presses de l’Inalco","platform":"openedition","isbns":["9782858312634","9782858312641"],"description":"KinoFabula interroge les images du cinéma dans leur rapport originel et sans cesse renouvelé avec la littérature sous toutes ses formes – fable, conte oral, poésie, théâtre ou roman, et analyse les relations et les modes de circulations entre les œuvres. Relations intergénériques qui créent des objets hybrides comme la fable cinématographique, le ciné-skaz ou le poème cinégraphique. Relations intermédiales entre les mots de la littérature et les images du cinéma, commentaires a posteriori certes,mais favorisant, par la rétroaction, un retour sémantique sur les textes et nous renseignant sur leurs régimes interprétatifs. Relations temporelles qui imbriquent l’Histoire – passé historique – dans les histoires – présent de l’énonciation fictionnelle.\n\n\tLes œuvres qui entrent ainsi en dialogue sont des espaces textuels ou visuels de transition, des objets à jamais imparfaits et inachevés qui aspirent à être complétés comme une traduction complète le texte d’origine et en révèle le mode de visée (Walter Benjamin). En s’ajoutant, se commentant, se traduisant et se réécrivant les unes les autres, elles participent du mouvement même de la culture qui ne cesse de métisser et de réinterpréter ses propres données.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Adaptation"]},"reason":"Circulations entre fable, poesie, theatre, roman et cinema explicites dans le resume.","index":49,"bookId":"book-d1a2610cb0ec6a3105fa"},{"source_id":"scholarvox:88973333","title":"L'analyse de séquences Ed. 6","authors":["Jullier, Laurent"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200641313","9782200643423"],"description":"Comment analyser une séquence de film ? Qu'on s'y lance pour le plaisir ou dans le cadre d'un examen, il est prudent de partir bien équipé.Ce livre est conçu comme une boîte à outils. Il fournit les bases indispensables à l'exercice d'analyse, en matière aussi bien de technique que d'esthétique. Chacun des outils est présenté à l'aide de tableaux, de photogrammes et d'exemples de films puisés dans toute l'histoire du cinéma. Nul besoin d'être un cinéphile accompli pour se les approprier.Des descriptifs d'épreuves, enfin, parmi celles qui comportent une analyse de séquence, sont fournis et commentés : l'option cinéma du bac et des agrégations de lettres et d'arts plastiques, les concours d'entrée à l'ENS (Lyon et Paris), à la Fémis, à Louis-Lumière et à l'INSAS (Bruxelles).Cette cinquième édition refondue propose quatre nouveaux exemples d'analyse : Gilda (Charles Vidor, 1946), Beau-père (Bertrand Blier,1981), Les Amitiés maléfiques (Emmanuel Bourdieu, 2006), Control (Anton Corbijn, 2007).","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Analyses de films"]},"reason":"Methodes et exercices d analyse de films; revue critique avec analyses de films identifies.","index":50,"bookId":"book-44dd4d30a5e5d485ce9a"},{"source_id":"scholarvox:88921466","title":"L'analyse des films","authors":["Aumont, Jacques","Marie, Michel"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200628208","9782200628673"],"description":"Depuis sa première édition il y a 25 ans, l’Analyse des films est devenu un classique des études cinématographiques. Après avoir défini l’activité analytique, l’ouvrage présente successivement l’analyse du fait narratif et du récit, l’analyse plastique et sonore, et enfin le rapport à l’histoire. Jacques Aumont et Michel Marie y démontrent que l’analyse prend tout son sens si elle débouche sur une réflexion générale, qui dépasse le cas particulier de l’œuvre étudiée. Ils se sont efforcés de décrire et de commenter les meilleures analyses publiées en français et dans d’autres langues, et d’en retenir les acquis méthodologiques. Les divers outils d’analyse sont illustrés à l’aide de tableaux, de schémas ou de photogrammes, et portent sur des films puisés dans toute l’histoire du cinéma. Cette quatrième édition enrichie d’exemples récents de l’Analyse des films est plus que jamais « une bible et un sésame » pour tous les étudiants en cinéma et les cinéphiles.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Analyses de films"]},"reason":"Methodes et exercices d analyse de films; revue critique avec analyses de films identifies.","index":51,"bookId":"book-7703e091c5cc55c83311"},{"source_id":"scholarvox:88921642","title":"L'analyse des films en pratique : 31 exemples d'analyse filmique commentés","authors":["Boutang, Adrienne","Clémot, Hugo","Jullier, Laurent"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200620394","9782200622763"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Analyses de films"]},"reason":"Methodes et exercices d analyse de films; revue critique avec analyses de films identifies.","index":52,"bookId":"book-980a9426245eafa317b6"},{"source_id":"scholarvox:88835009","title":"L'Anticyclopédie du cinéma","authors":["Vincenot, Emmanuel","Prelle, Emmanuel"],"publisher":"Wombat","platform":"scholarvox","isbns":["9782374980478","9782374980492"],"description":"Qui est Alain Delon ?\nCombien nous coûte Luc Besson ?\nQuelle est la couleur du tapis rouge de Cannes ?\nComment devient-on membre de l'Office catholique du cinéma ?\nLes films doivent-ils être projetés à l'envers dans l'hémisphère sud ?...\nVoici quelques-unes des questions essentielles auxquelles vous trouverez une réponse en lisant cet ouvrage décalé et irrévérencieux, mais toujours cinéphile, qui parle du 7e Art comme personne ne l'avait fait auparavant.\nUne parodie de guide savant, gentiment déjantée et férocement drôle !","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinématographie"]},"reason":"Synthese generale, histoire des mouvements et cinematographies; reference/parodie encyclopedique pour Anticyclopedie, pas traite conceptuel.","index":53,"bookId":"book-f4be41bf5e2e021bbf5a"},{"source_id":"scholarvox:88952257","title":"L'art de voir un film : Entretiens avec Hervé de Bonduwe","authors":["Collet, Jean","Bonduwe, Hervé de"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9782705689971","9791037034786"],"description":"Jean Collet aime citer François Truffaut : \"Dans la vie, il y a les compliqueurs et les simpli?eurs\". Répondant aux questions d'un ami spectateur, Jean Collet simpli?e ici pour nous le cinéma. Où trouve-t-on l'art dans le 7ème art? Comment échapper à la prouesse trompeuse, à la manipulation qui fascine? Comment, devant un grand film, passer de l'éblouissement à la conviction? Paradoxalement, le film vit de sa relation avec le spectateur, alors que l'oeuvre échappe à son réalisateur. 0L'oeuvre d'art est révélation. C'est pourquoi le cinéma demande, en même temps qu'il engendre, une conversion du regard. Cette conversion du regard, ce livre a l'ambition d'y conduire le lecteur. Le jeune 7ème art nous a beaucoup donné. Ce sont les spectateurs avertis et exigeants qui lui offrent un avenir.0.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":54,"bookId":"book-c42f12b2e89ce5504c78"},{"source_id":"openedition:septentrion--46052","title":"L'art des foules","authors":["Emmanuel Plasseraud"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757403358","9782757421604"],"description":"Chacun va au cinéma, aujourd'hui, avec le sentiment de vivre une expérience partagée, mais en même temps intime et singulière. La réception filmique ne fut pourtant pas toujours envisagée ainsi. Durant la période « muette », en France, elle était considérée comme un phénomène ressortissant aux lois de la psychologie collective. Les films ne s'adressaient pas à des individus mais à la foule.\n\tLa foule était au centre des préoccupations d'une époque que Gustave Le Bon a baptisé d'« ère des foules ». Sa Psychologie des foules est demeurée l'emblème de la psychologie sociale naissante. Pourtant, la vision négative des foules qui s'y dessine ne fut pas la seule manière de concevoir ce phénomène. La foule est aussi apparue comme l'expression d'une volonté de renouveau du communautarisme et du spiritualisme, au sein d'un monde moderne qui s'orientait vers l'individualisme et le matérialisme.\n\tC'est par rapport à ces débats que des critiques, cinéastes et théoriciens (Canudo, Gance, Delluc, Epstein, L'Herbier, Moussinac, Faure) envisagèrent d'octroyer au cinéma un rôle capital. Ils voulurent que ce spectacle populaire devienne l'art des foules. Ce n'était qu'ainsi qu'il pouvait offrir aux foules des moments de communion et d'élévation spirituelle, et qu'en même temps, cette mission « religieuse » conférée à l'art par le romantisme serait sauvée. Il était donc destiné à prolonger les idéaux romantiques dans le monde moderne, tout en préparant la venue d'un homme nouveau capable de fusion psychique, voire de télépathie.\n\tPsychologies des foules, histoire de l'art, pacifisme, universalisme, socialisme, occultisme et sciences psychiques sont ici convoqués pour exhumer les enjeux idéologiques de cette grandiose et utopique théorisation du cinéma comme Septième Art et de la réception filmique comme phénomène collectif.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":55,"bookId":"book-5d5461bc57986afba3a6"},{"source_id":"scholarvox:88927292","title":"L'autoportrait en cinéma","authors":["Grange, Marie-Françoise"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753506756","9782753526952"],"description":"Autoportrait en cinema - Marie-Françoise Grange","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":56,"bookId":"book-94897c76707223f6c9d5"},{"source_id":"scholarvox:88921486","title":"L'Avant-garde au cinéma","authors":["Albera, François"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200260057","9782200268602"],"description":"De 1995 à 2005, Lars von Trier et ses amis ont fait scandale par l'intransigeance de leurs manifestes, des déclarations provocantes à l'endroit de l'industrie du cinéma et des films censés appliquer leur programme. Ils proclamaient par là leur appartenance à une nouvelle « avant-garde », le Dogme. Ce mouvement, écartelé entre parodie et radicalité, a aujourd'hui vécu, mais il n'en a pas moins affiché les traits distinctifs d'une position au sein du champ cinématographique et de la société, dont les premières manifestations remontent au début des années 1920 : violence rhétorique, renversement des valeurs, politique de groupe, d'emblée pensée comme internationale, dépassement de l'art dans la vie. Ce livre entend reprendre la question de « l'avant-garde au cinéma » en s'interrogeant sur ses conditions de possibilité à la fin du XIXe siècle où la catégorie émerge dans les arts, en même temps que le cinématographe - qui ne peut y participer étant donné la nature du spectacle qu'il propose et ses modalités de production. Comment dès lors les avant-gardes artistiques ont-elles appréhendé le cinéma qui leur était extérieur, et comment celui-ci a-t-il vu se développer des positions d'avant-garde en son sein ? Dès les années 1920, on a voulu réduire l'avant-garde à un style, une école, un genre , avant de la cantonner dans le territoire à part d'une bohème ou, au contraire, on a souhaité voir « l'avant-garde nouvelle » s'inscrire dans le renouvellement du cinéma institutionnel (Astruc, 1946, Bazin, 1952). Ainsi, l'avant-garde n'a-t-elle de cesse de « finir » et de « revenir » dans les antagonismes qui sont loin de n'être qu'esthétiques. François ALBERA , professeur d'histoire et d'esthétique du cinéma à l'Université de Lausanne, a travaillé sur le cinéma soviétique des années 1920-1930, le cinéma français des années 1920 et le cinéma indépendant contemporain.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinématographie"]},"reason":"Synthese generale, histoire des mouvements et cinematographies; reference/parodie encyclopedique pour Anticyclopedie, pas traite conceptuel.","index":57,"bookId":"book-e1f989acc533f40a0bfd"},{"source_id":"scholarvox:88921886","title":"L'espace cinématographique : Esthétique et dramaturgie","authors":["Gaudin, Antoine"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200288532","9782200612139"],"description":"L’espace constitue un enjeu majeur des réflexions esthétiques et philosophiques sur le cinéma, autour duquel s’articule toute l’histoire des formes filmiques. Comment les films représentent-ils l’espace ? Comment l’organisent-ils par la mise en scène, le montage et le rapport image-son ? Quel(s) espace(s) vivons -nous au cinéma ? Comment influencent-ils notre façon de percevoir le monde et d’y penser notre situation ? Pour répondre à ces questions, l’ouvrage définit l’espace cinématographique comme une puissance dynamique de l’image en mouvement, dotée d’un fort impact sensoriel sur ses spectateurs. Cette approche cinéplastique et rythmique de l’espace trouve son aboutissement dans un concept original : l’ image-espace . L’ouvrage s’appuie sur l’analyse de nombreux films, et notamment sur le travail de réalisateurs tels que Buster Keaton, Orson Welles, Michelangelo Antonioni, Andreï Tarkovski, Gus Van Sant, ou encore Jia Zhang-Ke. Il se révèle particulièrement fécond pour comprendre les grandes évolutions du cinéma contemporain.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":58,"bookId":"book-9b809190b4fd2a4b1494"},{"source_id":"scholarvox:41001250","title":"L'essai et le cinéma","authors":["Gagnebin, Murielle","Liandrat-Guigues, Suzanne"],"publisher":"Editions Champ Vallon","platform":"scholarvox","isbns":["9782876733978","9791026705949"],"description":"L'essai et le cinema - Suzanne Liandrat-Guigues, Murielle Gagnebin","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":59,"bookId":"book-367f10a49fa4f56da631"},{"source_id":"scholarvox:88952545","title":"L'expérience du cinéma","authors":["Collectif"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9782705691189","9791037035158"],"description":"Juger le cinéma n'a jamais été la seule affaire des spécialistes. Le 7e art, dès sa naissance, a montré sa capacité à susciter toutes sortes de réactions, spontanées ou savantes, émerveillées ou inquiètes, rendant compte du rapport singulier qui se tisse entre le film et son spectateur. Ce qu'on interroge ici en priorité, ce sont donc moins les discours professionnels que l'expérience du cinéma au sens large, telle qu'elle se vit à de multiples niveaux : chez le spectateur cultivé, fasciné ou révulsé, mais rarement indifférent ; chez les critiques bien sûr, dans les moments particuliers où, face à des oeuvres inattendues, leurs convictions esthétiques sont ébranlées ; enfin, chez le spectateur ordinaire, dont le goût fut longtemps ignoré alors que son expérience est par excellence le terrain où s'observent les échos et les effets du cinéma dans la société.\nCette entreprise, par son étendue, exigeait la collaboration de plusieurs disciplines. Ainsi se donnent à voir d'un article à l'autre les contours mouvants de l'expérience du cinéma, qui se transforme en circulant entre les époques, les individus, les communautés interprétatives, et rassemble finalement les publics.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":60,"bookId":"book-9fa1036dc77a85eddca7"},{"source_id":"scholarvox:88921750","title":"L'image : Peinture, photographie, cinéma : des origines au numérique","authors":["Aumont, Jacques"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200628215","9782200629076"],"description":"Actualisé à l'occasion de cette nouvelle édition, ce livre est une synthèse originale et passionnante des savoirs contemporains sur l'image, moyen d'expression et de communication, et plus profondément, manifestation de la pensée.Les grands problèmes que pose l'image sont développés autour de six approches successives : l'image est un phénomène perceptif (physiologie de la perception), mais aussi l'objet d'un regard de la part d'un sujet spectateur (psychologie) ; elle établit un rapport avec ce spectateur par l'intermédiaire d'un médium et d'un dispositif spécifique (sociologie, médiologie) ; elle peut être utilisée à plusieurs fins et a des valeurs variables (anthropologie) ; son importance sociale a connu de grands moments de mutation (histoire) ; enfin, elle a des pouvoirs propres, qui la distinguent du langage et des autres manifestations symboliques humaines (esthétique).Toutes les images – faites à la main ou produites automatiquement, immobiles ou mouvantes – sont prises en considération dans cette enquête où l'auteur s'est efforcé de n'oublier aucune théorie, aucune approche, et qui prend en compte les développements les plus récents.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":61,"bookId":"book-abec080054ec42c129c3"},{"source_id":"openedition:septentrion--46661","title":"L'image paradoxale","authors":["Caroline Chik"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757401743","9782757421543"],"description":"À l’ère du numérique, les frontières entre les catégories, entre les états de l’image se sont ouvertes de manière évidente. L’image n’est plus nécessairement une image fixe ou une image animée mais, de plus en plus, les deux à la fois. Bien plus, il semble que le clivage « image fixe versus image animée » n’ait pas toujours eu cours. Un regard rétrospectif sur l’image optique nous enseigne qu’elle fut de tout temps travaillée par des liens étroits et féconds entre les deux états.Ce livre traite des relations entre fixité et mouvement qui se sont nouées tout au long de l’histoire de l’image optique, depuis ses origines jusqu’à ses formes les plus récentes. Il propose une analyse de ces nouvelles images au statut parfois ambigu entre fixité et mouvement, mais il s’interroge aussi, auparavant, sur les liens paradoxaux de la photographie au mouvement, et de l’image animée, à la fixité.S’appuyant sur de multiples dispositifs allant de la camera obscura aux animations interactives, il envisage l’image optique comme une et continue, sous un angle à la fois historique, esthétique et technique, libéré de certains schématismes. De cette image si répandue et souvent partiellement méconnue, image qui n’a cessé d’être pensée en termes d’opposition (entre fixité et mouvement, entre optique et numérique, entre archaïsme et modernité), il s’agit de relier, voire réconcilier les différents aspects, histoires et états, afin d’en mieux saisir les paradoxes et les problématiques spécifiques.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":62,"bookId":"book-f2ee24ccd9fa70f2eedf"},{"source_id":"scholarvox:88922004","title":"L'interprétation des films","authors":["Aumont, Jacques"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200617127","9782200620608"],"description":"Interpréter un film est la manière la plus naturelle et la plus personnelle d'y réagir. Mais l'interprétation est souvent critiquée pour sa subjectivité, qui la rend invérifiable. Le propos de ce livre est de montrer que cette activité inventive peut aussi être pratiquée avec profit, autant que l'analyse ou la critique.Il a existé plusieurs tentatives pour donner forme théorique rigoureuse aux procédures d'interprétation, toujours à propos d'œuvres écrites. Ce livre expose les principales de ces traditions, de l'exégèse et de l'herméneutique jusqu'à la déconstruction, et montre comment elles ont été, souvent sans le savoir, utilisées pour l'interprétation des films. On verra également qu'elles répondent à de nombreux problèmes de théorie du film, auxquels elles permettent d'apporter des réponses fécondes. Il s'agit en fin de compte de réhabiliter une attitude mal considérée et cependant essentielle, en montrant qu'elle n'est pas condamnée à l'erreur ni à l'arbitraire, mais qu'elle est la source même de toute compréhension.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":63,"bookId":"book-2938e71fb2f08e009b92"},{"source_id":"openedition:enseditions--40431","title":"L'écran de nos pensées","authors":[],"publisher":"ENS Éditions","platform":"openedition","isbns":["9791036204135","9791036204159"],"description":"Grande voix de la philosophie américaine du vingtième siècle, Stanley Cavell (1926-2018), héritier de Wittgenstein, s’est attaché sa vie durant à élargir le champ de la philosophie aux arts au service d’une philosophie du « langage ordinaire ». Jeune philosophe, nommé professeur à Harvard, il explora dans un séminaire d’esthétique, vingt ans avant Deleuze, le lien entre philosophie et cinéma. De Frank Capra à George Cukor, Terrence Malick, Arnaud Desplechin ou les frères Dardenne, un fil court, celui des lectures philosophiques de Stanley Cavell et des films qu’elles ont inspirés. Peu d’œuvres philosophiques ont autant marqué la création cinématographique et le champ des études cinématographiques que celle du philosophe de Harvard. De son chef-d’œuvre de 1971, La projection du monde, à ses derniers écrits sur le mélodrame, l’autobiographie et la critique, en passant par son livre sur la comédie hollywoodienne des années 1940, cet ouvrage éclaire l’ensemble de sa pensée. Il donne aussi la parole à trois cinéastes qui l’ont connu et qui ont été inspirés par ses écrits : Luc Dardenne, Arnaud Desplechin et Claire Simon. Il se penche, enfin, sur le lien que Cavell a entretenu avec Terrence Malick à Harvard dans les années 1960, jetant les bases d’une pensée du cinéma qui prend son départ dans notre expérience aussi bien collective qu’intime des films. Cette expérience qui nous unit ou nous rapproche des autres. Et qui nous permet aussi, plongeant en nous-mêmes, de nous éduquer.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":64,"bookId":"book-ad34571a8dca2d4e080e"},{"source_id":"scholarvox:88921900","title":"L'écriture cinématographique","authors":["Maillot, Pierre"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200014780","9782200259600"],"description":"L'auteur définit le cinéma, moyen d'expression personnelle, comme un art, non par ce qu'il montre mais par la façon de montrer. Pour apprendre cette écriture et apprendre à la lire, il aborde successivement les matériaux narratifs profilmiques, la réalité cinématographique, la construction du scénario, découpage et montage. Le matériau narratif. Les décors. Les temps. Les personnages. Actions, situations, segments narratifs. Le matériau cinématographique. Les lieux d'origine, le corps, la voix. Le cinéma et les autres arts. Les signifiants cinématographiques. La narration cinématographique. Position de la question. Le synopsis. Le scénario.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":65,"bookId":"book-762cfb41d03b273bac26"},{"source_id":"scholarvox:88952057","title":"La chambre d'à côté : Le décadrage absolu de Melville à Scorsese","authors":["Gil, Marie"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9782705694555","9791037027511"],"description":"La chambre d'à côté est ce lieu où se déroule véritablement le récit et qui, dans certaines œuvres, reste inaccessible au lecteur. Relégué dans l'ailleurs, décadré, celui-ci demeure, jusqu'à la fin de l'histoire, ignorant : «Qu'est-ce qu'il s'est passé?», comme l'écrivait Deleuze à propos de James. Tel secret, tel personnage, existent-ils réellement? Pourquoi me raconte-t-on cette histoire ? Dans ces récits, le lieu du sens seul est désigné. La chambre d'à côté, métaphore ou figure, n'a qu'une valeur indiciaire : ce qu'elle désigne, c'est une dualité fondamentale de l'espace du monde, entre un ici vide et un ailleurs inaccessible – mais un ailleurs qui porte l'essence de toutes choses. Or n'est-ce pas le Réel même, défini comme l'irreprésentable, qui est ainsi désigné? Par cette figure du décadrage narratif, romanciers, cinéastes et peintres n'atteignent-ils pas l'essence de tout récit : signifier le réel véritable, qu'on appelle aussi l'immanence? Ce serait paradoxalement par la désignation de l'ailleurs que l'on atteindrait l'essence véritable de ce qui est là.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":66,"bookId":"book-019191306776d8d19773"},{"source_id":"openedition:septentrion--101462","title":"La critique d'art à l’écran (Tome 2)","authors":["Dominique Vaugeois","Sylvain Dreyer"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757432389","9782757432587"],"description":"Filmer l’écrivain, est-ce filmer une vie, un statut institutionnel, une parole ? L’émission littéraire ou la critique filmée sur internet ont-elles pour but de rapprocher le public de littérature ? La dimension patrimoniale et didactique du film sur la littérature, la starisation liée à l’incarnation des auteurs semblent dominer les discours cinématographiques et télévisuels. Peut-on alors parler de critique ? Ou avons-nous affaire à la constitution d’un pur objet de culture ? Les études ici rassemblées témoignent qu’un discours critique est en jeu dès lors que le cinéma ou la télévision engagent un geste de mythification ou de démystification. L’ouvrage mettra également en avant les ressources propres dont le film dispose pour explorer ce qui apparaît comme au cœur de l’expérience littéraire : la production d’effets qui dépassent le fonctionnement linguistique et relèvent de la matérialité de l’écrit, du corps, de la naissance des images, des rythmes et des sons et par-dessus tout sans doute, comme le cinéma, d’une méditation sur le temps et la mémoire.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":67,"bookId":"book-5c6a919d3802cf7f2492"},{"source_id":"scholarvox:88969391","title":"La critique de cinéma","authors":["Prédal, René"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200255527","9782200340100"],"description":"Attachée à l'étude des oeuvres, la critique de cinéma s'est imposée, singulièrement en France, comme un genre à part, bien distinct des approches historique et critique. Réputée subjective ou idéologique et faisant l'objet de reproches récurrents, elle n'en est pas moins à prendre en considération : seule garante de la légitimité du patrimoine, elle est aussi nécessaire à l'accompagnement du plaisir du spectateur qu'à l'approfondissement des recherches esthétiques propres aux études cinématographiques. Vraie synthèse, cet ouvrage évoque l'histoire et l'influence de l'activité critique : il en spécifie la nature et les fonctions, en expose les combats passés et actuels, en présente les grands courants, et s'interroge sur cette « politique des auteurs » qui en est devenue la méthodologie la plus répandue. Il se prononce enfin sur la capacité actuelle de renouvellement du genre, face à la remise en cause de sa place dans la presse comme dans l'évolution de la création cinématographique. Nature et fonction de la critique. Histoire des revues de cinéma. Les combats de la critique. Critique, théorie, idéologie. La politique des auteurs. La critique en crise.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":68,"bookId":"book-422e0d7ee6645dbe9f48"},{"source_id":"openedition:septentrion--21299","title":"La critique d’art à l’écran","authors":["Dominique Vaugeois","Sylvain Dreyer"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757420195","9782757420591"],"description":"Le film est-il à même de renouveler notre rapport aux arts plastiques ? Est-il capable, surtout, de tenir un discours critique spécifique sur les œuvres, l’histoire de l’art ou l’esthétique ?\n\tÀ l’intérieur du champ du « film sur l’art » auquel l’époque accorde une pleine visibilité, le propos de cet ouvrage est de configurer une zone particulière, celle des médiations cinématographiques du savoir sur l’art. Sont envisagés les films qui ouvrent un espace critique, c’est-à-dire ceux qui exhibent leur source d’énonciation ou articulent un discours argumenté à propos de l’œuvre, du medium ou de l’art en général. Quatre pistes de réflexion majeures sont abordées : capacité du cinéma à construire un regard critique sur la production artistique, à capter le geste du peintre afin de percer le secret d’un style, à représenter les musées et les publics, enfin à remettre en question le partage des hiérarchies et des genres.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":69,"bookId":"book-dc1ed89db880e8bf8296"},{"source_id":"scholarvox:88840394","title":"La Direction de spectateurs : Création et réception au cinéma","authors":["Collectif"],"publisher":"Les Impressions nouvelles","platform":"scholarvox","isbns":["9782874493027","9782874494932"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":70,"bookId":"book-f5051562330cd8c4d73e"},{"source_id":"openedition:septentrion--9449","title":"La machine à voir","authors":["Viva Paci"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757403785","9782757414071"],"description":"Arriver au cinéma en retard, la séance commencée, la noirceur déjà totale, les images déjà déchainées sur l'écran, et juste des apparitions (des formes, des corps, des mouvements, des visages, des sons) qui attirent l'attention…\n\t\n\tLes films enchaînent une relation sensorielle avec les spectateurs faite de petites agressions, de fragments spectaculaires. Si le cinéma narratif relègue en général le spectateur à une position sécurisante d'observateur-voyeur, au contraire, le cinéma des attractions interpelle directement le spectateur, destinataire privilégié du plaisir du spectacle, stimulant ses sens et ses émotions.\n\t\n\tLe cinéma est une machine à voir. Dès sa naissance il a généré une nouvelle manière stupéfiante de voir : c'est ainsi que les premiers théoriciens du cinéma ont commencé à en parler. Dans ce livre, des moments de la théorie classique (le montage des attractions chez Eisenstein) se trouveront côte à côte avec des exemples d'images contemporaines. Ainsi, au fil des pages, nous traiterons du concept d'attraction, d'un cinéma où fiction et documentaire se croisent (les films de Werner Herzog), de l'univers du numérique où les images de synthèse infiltrent les prises de vue réelles et de nouvelles formes audiovisuelles où le cinéma entre dans l'espace du musée.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":71,"bookId":"book-7897334cadff624c8368"},{"source_id":"scholarvox:88883971","title":"La nuit sera noire et blanche : Barthes, La Chambre claire, le cinéma","authors":["Narboni, Jean"],"publisher":"Capricci Editions","platform":"scholarvox","isbns":["9791023904116","9791023904123"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":72,"bookId":"book-d061a015c42216f5596f"},{"source_id":"openedition:aaccademia--3810","title":"La parata dei fantasmi","authors":["Alessandro Cappabianca"],"publisher":"Accademia University Press","platform":"openedition","isbns":["9788831978095","9788899982980"],"description":"L’invenzione del cinema, perfezionamento della fotografia, ha dato modo agli umani di vedere doppi realistici di corpi in azione, in realtà ombre, fantasmi, spettri, prima muti, poi parlanti, suscitabili a piacere a ogni proiezione, con il solo limite d’essere condannati a ripetere ogni volta gli stessi gesti, a pronunciare le stesse parole. Eppure questo limite non è solo una condanna, non è solo ripetizione, non ricalca necessariamente i sentieri dell’identico. Il cinema, in certi casi, è in grado di veicolare con le sue immagini qualcosa come una quintessenza, e quelle ombre, quegli spettri, quei doppi, sono in grado di dirci, sul nostro corpo, sul rapporto con il mondo, sui movimenti, sui gesti, sul tempo, sull’identità, sulla memoria, sul mito, qualcosa di rilevante anche sul piano filosofico.\n\tÈ quanto si spera risulti dalla lettura di queste note, avvertendo comunque che esse, nel loro andamento non sistematico, si appoggeranno a oggetti e soggetti filmici in apparenza eterogenei, da Pasolini a Orson Welles, da Rossellini a Bela Tarr, da Raul Ruiz a Bressane, da Tsai Ming Liang a Cronenberg, da Ejzenštejn a Godard, da Dreyer a Scorsese, da Fellini a Gianikian e Ricci Lucchi, da Chantal Akerman a Twin Peaks 3, non senza qualche rapido excursus teatrale, tra Artaud e Carmelo Bene.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":73,"bookId":"book-1fa4654a3ed04b47c60c"},{"source_id":"openedition:septentrion--29081","title":"La part du spectateur","authors":["Florence Gravas"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757413616","9782757427866"],"description":"Quel type d'expérience faisons-nous quand nous « regardons un film » ? Bien que cette formule consacrée ne prenne pas en compte la complexité du voir/entendre spectatoriel, elle souligne néanmoins une forme d’équivocité à propos de ce qu’on « regarde », comme de ce qui est ainsi mis en jeu. Le présent essai s’efforce de rendre compte des différentes modalités d’appréhension de l’image filmique par le spectateur.\n\tL’auteure a choisi de travailler au plus près de la texture filmique en analysant précisément de courts extraits de films. Il s’agit d’entrer dans l’expérience que proposent Caché, de M. Haneke, Mulholland Drive et Lost Highway, de D. Lynch, Eût-elle été criminelle..., de J.G. Périot, Valse avec Bachir, d’A. Folman, et Le mystère Picasso, de H.G. Clouzot, afin de comprendre tant ce qu’un film fait au spectateur, que ce que le spectateur fait de ce qu’il perçoit.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":74,"bookId":"book-e5dc715967899693a036"},{"source_id":"scholarvox:88921757","title":"La philosophie du cinéma","authors":["Chateau, Dominique"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200247928","9782200258313"],"description":"Réflexion sur les relations entre philosophie et cinéma, abordant trois aspects : la représentation du philosophe à l'écran, l'adaptation cinématographique de textes philosophiques et l'ouverture philosophique possible d'un film. L'étude explicite les liens qui unissent cinéma et philosophie dans un contexte historique et se clôt sur une théorie esthétique du cinéma.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":75,"bookId":"book-988a6f919244680f6737"},{"source_id":"scholarvox:88927287","title":"La rencontre : Au cinéma, toujours l'inattendu arrive","authors":["Aumont, Jacques"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753504929","9782753526921"],"description":"Le cinéma est, de bien des façons et à bien des titres, un art de la rencontre. Dans la filiation des frères Lumière, filmer, c’est aller, tout simplement, à la rencontre du réel, du plus lointain au plus familier ; dans cette aventure, le familier devient étrange, l’étranger devient proche : c’est sur ce paradoxe que sont fondés le cinéma ethnographique et le documentaire. Dans la voie Méliès, le cinéma est une rencontre avec l’imprévu, l’improbable ou l’impossible ; tout le cinéma fantastiq...","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":76,"bookId":"book-c458dacd660e34d31f56"},{"source_id":"scholarvox:88927291","title":"La subjectivité au cinéma : Représentations filmiques du subjectif","authors":["Chateau, Dominique"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753517233","9782753561670"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":77,"bookId":"book-f2aadd601aa628f2cf28"},{"source_id":"scholarvox:88921472","title":"La valeur d'un film : Philosophie du beau au cinéma","authors":["Dufour, Eric"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200289959","9782200612894"],"description":"Qu'est-ce qui permet de juger de la qualité d'un film ? Sur quels critères ? Cette question fait écho à la question plus générale du beau dans l'art : qu'est-ce que le beau ? Cet ouvrage tente d'y répondre en proposant une réflexion sur ce qui fait la valeur d'un film et sur la façon de l'estimer. Contextes artistique et sociopolitique, référents cinématographiques et historiques sont bien entendu des débuts de réponse, mais l'auteur nous apprend surtout qu'il n'y pas de \"bons films\" ou de \"beaux films\", c'est-à-dire des films qui posséderaient une valeur et d'autres pas.0Selon lui, tous les films ont une valeur dès lors qu'ils impactent notre vie d'une façon ou d'une autre. Pour étayer son propos, l'auteur s'appuie sur une analyse philosophique des concepts abstraits et subjectifs du \"jugement\", du \"goût\" et de la \"valeur\", ainsi que sur une analyse factuelle basée sur de nombreux exemples de films.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":78,"bookId":"book-cf84c954705bf3f586cf"},{"source_id":"openedition:pupo--784","title":"La vie filmique des marionnettes","authors":[],"publisher":"Presses universitaires de Paris Nanterre","platform":"openedition","isbns":["9782821826755","9782840160212"],"description":"DES PREMIERS FILMS Pathé aux écrans numériques, la marionnette a connu une vie filmique à éclipses, surgissant soudain et par éclats chez les plus grands, de Chaplin à Roberto Benigni, de Renoir et Bergman à Spielberg, Kitano et Tim Burton. Longtemps confinée dans l’animation, elle connaît aujourd’hui un spectaculaire retour sur les écrans du monde entier. Plus subversive que mélancolique, elle est cette créature double qui ne cesse de se libérer des liens qui l’assujettissent, dans le mutisme et l’humiliation, au Montreur ventriloque, au Père, au Deus/Diabolus ex machina. Elle est au cinéaste, à l’acteur, au spectateur ce que le Sphinx est à Œdipe : riche d’une vie sauvage, obscène, archaïque à laquelle il leur faut un temps se confronter. À travers ces corps de frontière en constantes mutations, les miroirs grossissants du cinéma nous renvoient les images libératrices d’une modernité en travail, entre retours à l’enfance, métamorphoses burlesques et passages vers d’inquiétantes ou sublimes étrangetés. Pour sortir de l’ombre la vie filmique des marionnettes, Laurence Schifano, Professeur d’Études cinématographiques à l’Université Paris 10, a rassemblé ici des historiens et des chercheurs dont les domaines de recherche se situent aux confins de la psychanalyse, de la littérature, du théâtre et du cinéma.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":79,"bookId":"book-387089fab977a20d0874"},{"source_id":"scholarvox:88952290","title":"Le ciné-capital,  d'Hitchcock à Ozu : Une lecture marxiste de Cinéma de Gilles Deleuze","authors":["Fujita, Jun"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9782705695347","9791037011145"],"description":"L'argent est l'envers de toutes les images que le cinéma montre et monte à l'endroit \" écrit Gilles Deleuze dans le deuxième volet de Cinéma. Le capital est toujours derrière le cinéma. Le Capital hante Cinéma du début à la fin. C'est donc une lecture marxiste du diptyque composé de L'Image-mouvement et L'Image-temps que propose Jun Fujita dans Ciné-capital. Comment fonctionne le mode de production ciné-capitaliste ? Comment celui-ci fait-il produire de la plus-value aux images ? Pourquoi et comment s'approprie-t-il le travail même du spectateur ? En quel sens peut-on soutenir qu'Eisenstein et Hitchcock ont anticipé l'arrivée de la New Economy des années 1990 (dématérialisation du travail et financiarisation de l'économie) ? Quand et comment les images s'insurgent-elles contre l'exploitation ciné-capitaliste ? Comment se mettent-elles à valoir pour elles-mêmes ? Pourquoi le cinéma politique, depuis Straub et Huillet, a-t-il cessé de privilégier le tournage au bord de la mer ? Qu'est-ce qui permet à Deleuze d'affirmer qu'Ozu est un cinéaste de gauche ? Telles sont quelques-unes des questions abordées dans Ciné-capital.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":80,"bookId":"book-2e1ab4be1510d30710c8"},{"source_id":"scholarvox:88952289","title":"Le cinéaste au travail : autoportraits","authors":["Tinel, Muriel"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9782705691905","9791037012470"],"description":"\"S'éloignant de la sphère strictement intime, le cinéaste autoportraitiste ne revendique pas son individualité, mais sa position et son savoir-faire d'artiste dans un \" moi-ici-maintenant \" du film et, par extension, du cinéma, pour se représenter au travail. À travers un corpus varié de films, Muriel Tinel-Temple explore les postures du cinéaste (disparition du visage au profit des mains), son espace intime (\" atelier \" et paysage intérieur), l'inscription de sa subjectivité par le regard et la voix ainsi que la visibilité du film comme support et matériau. L'autoportrait cinématographique ouvre, enfin, vers une mise en scène de la mémoire du cinéma par le cinéma.\"--Page 4 of cover.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":81,"bookId":"book-14e4ed52fa093217fb99"},{"source_id":"scholarvox:88938400","title":"Le cinéaste et le philosophe","authors":["Grosos, Philippe"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753578852","9782753589995"],"description":"À quelles conditions est-il possible de mettre en rapport l'art d'un cinéaste et la pensée d'un philosophe sans subordonner l'un à l'autre ? Est-il envisageable que leurs œuvres puissent entrer en correspondance au point de dévoiler une origine intuitivement commune ? Et si tel devait être le cas, quelle serait l'incidence d'un tel propos sur ce qu'habituellement nous nommons esthétique ? Les trois études proposées dans ce livre mettent en évidence ce qui permet de rapporter la totalité de l'œuvre d'un cinéaste et celle d'un philosophe l'une à l'autre. Avec le soutien de l'université de Poitiers.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":82,"bookId":"book-ba4087723f20ea51461a"},{"source_id":"openedition:pup--79818","title":"Le cinéma argentique au xxie siècle","authors":["Monise Nicodemos"],"publisher":"Presses universitaires de Provence","platform":"openedition","isbns":["9791032004234","9791032005781"],"description":"La collection ARTS rassemble des ouvrages de recherche sur l’histoire des arts et sur la théorie et la pratique des arts contemporains.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":83,"bookId":"book-391308a7f37e1e098702"},{"source_id":"scholarvox:88807999","title":"Le Cinéma de répertoire et ses mises en scènes","authors":["Chevrier, H-Paul"],"publisher":"L'instant même","platform":"scholarvox","isbns":["9782895023265","9782895027744"],"description":"Du modernisme des années 1960, en passant par le réalisme politique des années 1970, le postmodernisme des années 1980 et 1990, jusqu'aux premières décennies du cinéma du numérique, le cinéma de répertoire rayonne aussi dans les cinématographies nationales. Enrichi de tableaux récapitulatifs regroupant les films essentiels pour chaque période donnée, Le cinéma de répertoire et ses mises en scène propose une rétrospective historique d'un cinéma indépendant tantôt lumineux, tantôt désabusé, mais jamais à court d'inventivité.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinématographie"]},"reason":"Synthese generale, histoire des mouvements et cinematographies; reference/parodie encyclopedique pour Anticyclopedie, pas traite conceptuel.","index":84,"bookId":"book-aece4e04c260e26ccc0e"},{"source_id":"scholarvox:88921377","title":"Le cinéma en couleurs","authors":["Martin, Jessie"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200270322","9782200290009"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":85,"bookId":"book-c6c42538f102592d9102"},{"source_id":"openedition:eua--1023","title":"Le cinéma et ses publics","authors":["Emmanuel Ethis"],"publisher":"Éditions Universitaires d’Avignon","platform":"openedition","isbns":["9782357680241","9782357680982"],"description":"Qu’est-ce que la sociologie, et plus précisément la sociologie du cinéma ? Comment, à l’heure des productions de masse et de l’individualité, le cinéma peut-il rester cet outil sociologique précieux, toujours au service de son public ? Emmanuel Ethis montre ici de quelle manière cette « pratique culturelle » ouvre la porte aux observations sociologiques, nous transforme et, partagée par tous, nous rassemble. Déterminants sociaux et phénomène d’imitation sont au cœur de cette conférence, ponctuée d’anecdotes visant à éclairer le lecteur et lui permettre de s’ouvrir à la réalité qui l’entoure.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéma et société"]},"reason":"Biopouvoir, corps social, frontieres, savants representes, publics, precarite, ville, migrations ou critique amateur : angle social principal.","index":86,"bookId":"book-167f5e22f5042a116362"},{"source_id":"scholarvox:88826465","title":"Le Cinéma infiltré : Un Nouveau Journalisme","authors":["Lewis, Grover"],"publisher":"Capricci Editions","platform":"scholarvox","isbns":["9791023900675","9791023900712"],"description":"« Contre toute attente, Peckinpah s arre te quelques instants plus tard pour inviter le journaliste a","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Réalisation"]},"reason":"Multicaptation documentaire du theatre; recits journalistiques de tournages, corrobores chez Capricci.","index":87,"bookId":"book-7bcdea2d9de8d3f24d0f"},{"source_id":"openedition:pur--87745","title":"Le cinéma ou le dernier des arts","authors":["Luc Vancheri"],"publisher":"Presses universitaires de Rennes","platform":"openedition","isbns":["9782753574458","9782753577473"],"description":"Du cinéma qui naît à la fin du xixe siècle à celui qui s’expose aujourd’hui au musée s’est jouée une histoire en trois temps, dont chacun est venu décrire un usage théorique et social du signifiant « cinéma ». Le premier consacre un appareil d’enregistrement et de projection des images en mouvement qui, parmi d’autres, a réussi à imposer un modèle technique et industriel de production des films. Point d’arrivée d’une culture visuelle façonnée par les panoramas, la photographie, le chemin de fer, la lanterne magique et les jouets optiques, le cinématographe consigne une vaste iconographie documentaire avant de s’ouvrir aux formes divertissantes du spectacle. C’est le moment Lumière. Pourtant, dès le début des années 1910, ce premier moment historique est contrarié par une demande d’art qui va profondément modifier son profil culturel et social. Si les avant-gardes ont été divisées sur ce que devait être le cinéma, partagées entre ceux qui y voyaient le moyen d’une révolution de l’art et ceux qui le comprenaient comme le réformateur du système des Beaux-Arts, l’art s’est toutefois imposé comme sa nouvelle condition historique. C’est le moment Canudo. Le troisième moment cinématographique, lui, coïncide avec l’expansion technologique de la cybernétique qui l’impose sous la forme quasi illimitée de l’expanded cinema. Le cinéma cessait d’être le nom d’un art singulier pour devenir celui d’une utopie politique et esthétique. C’est le moment Youngblood.\n\n\tCet essai se propose de reprendre l’histoire de ces moments cinématographiques et fait l’hypothèse que le cinéma ne s’est maintenu septième dans la suite des arts qu’au prix d’un conflit de définitions qui ne s’est pas achevé avec la généralisation de son modèle économique.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":88,"bookId":"book-6f31861a1645a6f9ab3b"},{"source_id":"scholarvox:88927282","title":"Le cinéma, et après ?","authors":["Scheinfeigel, Maxime"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753510470","9782753527140"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":89,"bookId":"book-0ea16a252eba06180517"},{"source_id":"scholarvox:88936944","title":"Le découpage au cinéma","authors":["Moure, José","Amiel, Vincent","Mouëllic, Gilles"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753549920","9782753561427"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":90,"bookId":"book-71258fdb81ba3c858680"},{"source_id":"openedition:pusl--10904","title":"Le film de famille","authors":[],"publisher":"Presses universitaires Saint-Louis Bruxelles","platform":"openedition","isbns":["9782802801610","9782802804390"],"description":"Qui s'intéresse au film de famille dans la construction de la mémoire collective et individuelle ? C'est à cette question que tente de répondre cet ouvrage.\n\n\tLa recherche scientifique actuelle se révèle assez disséminée, car plusieurs disciplines analysent ce nouveau support et l'interrogent à l'aune de leur méthode.\n\n\tL'histoire, l'anthropologie et l'approche sémio-pragmatique apportent des regards complémentaires. Leur analyse saisit la mémoire collective à des stades différents : les rapports humains, la mise en images de ces liens, et l'histoire telle qu'elle se tisse à travers ces relations.\n\n\tL'analyse peut aussi se faire à différentes échelles : individuelle, quand elle saisit le parcours d'une adoption internationale, collective, quand elle jongle avec les problèmes de la conversation et de la valorisation de ces archives privées.\n\n\tDe ce kaléidoscope, des lignes de force se dégagent. L'interaction entre les disciplines et les pratiques donne sens au film de famille et à la place unique qu'il occupe dans la société.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Patrimoine"]},"reason":"Film familial comme support des memoires individuelles et collectives, histoire et anthropologie.","index":91,"bookId":"book-b201c0f7ecf97d02cdc7"},{"source_id":"openedition:pur--76602","title":"Le film en suspens","authors":["Philippe Ragel"],"publisher":"Presses universitaires de Rennes","platform":"openedition","isbns":["9782753540743","9782753561472"],"description":"Le présent essai se propose d’ouvrir une réflexion sur le concept de cinéstase, que nous avions forgé à l’origine pour désigner une situation filmique particulière observée lors de la longue halte au village dans Et la vie continue… (Abbas Kiarostami, 1992). Par ce néologisme, nous voulions signifier la tension dramaturgique auquel le film, alors, nous soumettait : d’un côté le mouvement incoercible du drame (kine), porté par la translation physique de la voiture et de ses occupants, de l’autre son immobilisation soudaine figurée par cette escale au village (stasis). Au cœur de ce rapport de type nouveau, cinéstasique, un mouvement d’une autre nature se faisait jour, à forte coloration persane en l’occurrence, mais où la puissance d’évocation du réel avait toute sa place. Dans ces moments de catalyse que constitue la cinéstase, les mobiles du scénario apparent passent en effet au point mort au profit d’une expérience d’une autre nature, sensible, poétique, paysagère. Une dépression narrative se crée, où quelque chose des impératifs dramatiques qui gouvernent le film se relâche, se met en suspens. Se proposant d’en vérifier plus largement l’opérativité, cet ouvrage s’inscrit dans une perspective d’extension et de transposition du concept, avec pour objectif de le mettre en danger, d’observer ailleurs sa manière de résonner (chez Rossellini, dans le cinéma muet), et partant d’en vérifier, ou pas, la transhistoricité.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":92,"bookId":"book-d0e0efe766052bb31116"},{"source_id":"openedition:pur--76659","title":"Le film sur l’art","authors":[],"publisher":"Presses universitaires de Rennes","platform":"openedition","isbns":["9782753536043","9782753561496"],"description":"Cet ouvrage dresse un état international des recherches menées sur ce « genre » cinématographique jusqu'ici peu étudié, hybride mais prolifique, au croisement de l'histoire de l'art et du cinéma documentaire : le film sur l'art.\n\n\tMontrer l'artiste au travail, présenter la biographie d'un artiste disparu, sa vie intérieure, son œuvre, entrer dans la logique de celle-ci pour en déplier la thématique ou les narrations qu'elle contient, analyser sa construction formelle, aborder une période ou suivre des évolutions stylistiques : ce sont autant de démarches qui peuvent unir, selon des modalités diverses, un cinéaste et un artiste ou un cinéaste et un historien de l'art (Diehl, Schmidt, Cassou, Huyghe, Sweeney…) – quand l'historien de l'art ne se fait pas tout simplement cinéaste (Haesaerts, Ragghianti). C'est que, de Warburg à Panofsky, de Focillon à Elie Faure et à Malraux, de Longhi à Francastel et Damisch, nombreux sont les historiens de l'art qui se sont préoccupés de ce que le cinéma pouvait apporter à leur discipline, tant au plan de la simple documentation que du modèle de perception qu'il engage par le découpage – les détails, les changements d'échelles –, le montage, la mise en mouvement et la projection par transparence.\n\n\tQuel bilan tirer de cette riche histoire du film sur l'art devenue quelque peu opaque (où sont ces films ? comment les voir ?) et que comprendre de l'histoire de ces productions qui, d'abord rattachées au documentaire, voire au cinéma pédagogique, ont ensuite trouvé une autonomie au sein du genre « film sur l'art » ? Quels liens furent noués entre historiens de l'art, critiques d'art et réalisateurs ? Quel apport à l'histoire de l'art cette production représente-t-elle ? Comment l'histoire de l'art et ses applications dans différents médias circulent-elles dans ces films, et quel effet cet intérêt pour l'art a-t-il pu produire en retour sur le cinéma « comme art plastique » ? Enfin, quelle est la situation présente de ce type d'approche ? Ces questions sont ici collectivement posées, débattues, développées.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Documentaire"]},"reason":"Etudes du film sur l art comme forme documentaire hybride.","index":93,"bookId":"book-cb8d50ce67b4e8633547"},{"source_id":"scholarvox:88969521","title":"Le film-après-coup","authors":["Eizykman, Claudine"],"publisher":"Presses Universitaires de Vincennes","platform":"scholarvox","isbns":["9782379240577","9782379240591"],"description":"Renversant les doctrines de la narration-représentation, Claudine Eizykman part de l'expérience originaire des avant-gardes et du cinéma expérimental. Sa méthode holistique, ses concepts ciselés, ses lectures éclairées des grands textes philosophiques, scientifiques, esthétiques à propos du cinéma, de Bergson à Warhol, ses analyses raffinées des films d'avant-garde, expérimentaux, narratifs, de Michael Snow à Men in Black constituent autant d'expériences de pensée en cinéma stimulantes et émancipatrices, une forme surprenante de film-après-coup\nCe premier recueil de textes inédits ou introuvables de Claudine Eizykman, flamboyante cinéaste-théoricienne, constitue une refondation radicale de la théorie du cinéma, élaborée et approfondie de 1970 à 2018. Renversant les doctrines fondées sur les standards de la narration-représentation, elle part du principe cinématographique comme mouvement paradoxal dont elle situe l'expérience originaire dans les avant-gardes et le cinéma expérimental, qui deviennent des lieux à partir desquels construire une pensée productive sur le cinéma. Sa méthode holistique, ses concepts ciselés, ses lectures éclairées de la quasi exhaustivité des grands textes philosophiques, scientifiques, esthétiques à propos du cinéma, de Henri Bergson à Andy Warhol, ses analyses raffinées des films d'Alexeïeff, Anger, Eggeling, Fihman, Kubelka, Len Lye, Man Ray, Mekas, Pat O'Neill, Richter, Snow, Willoughby, jusqu'à Men in Black ou Mulholland Drive, constituent à la lecture autant d'expériences de pensée en cinéma stimulantes et émancipatrices, une forme prenante, surprenante et excitante de film après-coup.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":94,"bookId":"book-4400c8b5c75473f429ca"},{"source_id":"scholarvox:88927278","title":"Le générique de film : De la lettre à la figure","authors":["Moinereau, Laurence"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753508149","9782753527003"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":95,"bookId":"book-1c70da6a31cc6189b2df"},{"source_id":"openedition:septentrion--105897","title":"Le hors-champ est dedans !","authors":["Jacopo Rasmi"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757432396","9782757432594"],"description":"Accompagner la contre-migration de Michelangelo Frammartino de Milan à l’arrière-pays méridional signifie être convié dans un univers cinématographique où le champ humain fourmille de ses hors-champs environnementaux. Dans les films du réalisateur italien, peu connu et étudié en France, la mort d’un berger semble donner naissance à un chevreau, des esprits végétaux envahissent un village et les objets quotidiens sont animés par des imprévisibles forces terrestres. À l’intérieur de cet univers rural où les présences vivantes se multiplient et se manifestent à notre regard, nous commençons à interroger le rapport entre notre attention et les milieux que nous habitons, la relation entre les problèmes écologiques et l’expérience audiovisuelle. Ces questions ne pourront émerger pleinement dans l’analyse des formes et des pratiques de Frammartino que grâce au dialogue avec les voix d’autres disciplines (d’Ernesto De Martino à Anna L. Tsing, jusqu’à Giorgio Agamben) et les images d’autres cinéastes (de Sharunas Bartas à Alice Rohrwacher).","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéastes"]},"reason":"Monographie Jacques Demy et etude de Michelangelo Frammartino; pas theorie generale du medium.","index":96,"bookId":"book-11ea8b9df604adaf71f2"},{"source_id":"scholarvox:88927274","title":"Le miroir et le simulacre : Le cinéma dans le monde devenu fable","authors":["Bertetto, Paolo"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753535633","9782753561502"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":97,"bookId":"book-8588d209bc1982417d17"},{"source_id":"openedition:septentrion--41250","title":"Le mythe, le miroir et le divan","authors":["Michel Serceau"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757401125","9782757421376"],"description":"Art au même titre que la littérature et la peinture, le cinéma a ses auteurs. La cause est entendue. Les intellectuels s'y intéressent alors qu'ils le méprisaient il y a quelques décennies. Mais le cinéma « populaire » perdure. Il y a toujours un cinéma « de masse », « de grande consommation », où, comme à la belle époque d'Hollywood, l'action et le spectacle restent au premier plan. C'est toujours lui qui a la faveur de ce que l'on appelle le « grand public ». Hiérarchie, clivage même, qui, ravivant des préjugés (« le cinéma est un divertissement d'ilotes », la grande production est une « usine à rêve ») occulte la fonction culturelle du cinéma.\n\tLe cinéma de grande consommation n'a jamais été en effet, contrairement à certaines assertions, un opium du peuple ou un divan du pauvre, mais un miroir de la psyché collective. Les grands cinéastes classiques, dont certains étaient déjà des auteurs, savaient, en utilisant les genres et les codes du spectacle, donner corps à l'imaginaire collectif. Et ce sans le ravaler ni le mépriser : ils revisitaient les grands mythes.\n\tLa sophistication de la production ne doit donc pas nous abuser. Des genres comme la sciencefiction, le fantastique… aidant, les mythes travaillent toujours les récits et les représentations. Quelques ruptures que l'on ait connues, quelque hiérarchie que l'on doive établir entre les œuvres, il y a ici une continuité, un héritage culturel, méconnu par la critique et l'université, que le présent ouvrage se donne pour tâche d'explorer.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":98,"bookId":"book-a239ba0b51bc19e7159a"},{"source_id":"scholarvox:88938396","title":"Le nocturne et l’émergence de la couleur : Cinéma et photographie","authors":["Langendorff, Judith"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753581715","9782753589964"],"description":"Ce livre étudie au plus près les techniques et les processus de création de réalisateurs et de photographes de la fin des années 1970 et des décennies suivantes (Stanley Kubrick, David Lynch, Brian de Palma, Francis Ford Coppola, Rut Blees Luxemburg, Chrystel Lebas, Gregory Crewdson, Bill Henson et autres). Chez eux, l'emploi de la couleur pour le nocturne s'est généralisé. Il est devenu de plus en plus intense et raffiné de telle sorte qu'il engendre un art de la métamorphose, du rayonnement de l'invisible et du passage d'un univers à un autre. Bref, un art du sublime explorant toutes les dimensions artistiques et philosophiques de la nuit. Avec une préface de Philippe Dubois et une postface de Baldine Saint Girons. Avec le soutien de l'EA 7343 – LIRA de l'université Sorbonne Nouvelle – Paris 3.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":99,"bookId":"book-36b384a3fec0dafad9aa"},{"source_id":"scholarvox:88952361","title":"Le peuple précaire du cinéma contemporain","authors":["Bortzmeyer, Gabriel"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9791037003331","9791037005182"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéma et société"]},"reason":"Biopouvoir, corps social, frontieres, savants representes, publics, precarite, ville, migrations ou critique amateur : angle social principal.","index":100,"bookId":"book-631edc632a42fd55c864"},{"source_id":"scholarvox:88958611","title":"Le regard cinéma en photographie Ed. 1","authors":["Lepetit-Castel, Gildas"],"publisher":"Eyrolles","platform":"scholarvox","isbns":["9782212391237","9782416017339"],"description":"Qu'elles défilent au rythme de vingt-quatre par seconde ou qu'elles se figent dans notre mémoire, les images des films nous marquent profondément. Véritables madeleines de Proust, elles sont à l'origine de la pratique photographique de Gildas Lepetit-Castel et de bien d'autres photographes. Arts lumineux par excellence, au sens propre comme au figuré, photographie et cinéma nécessitent tous deux de la lumière pour donner naissance aux images. Pourtant, ils partagent bien plus que cela. Quand le cinéma laisse couler le temps à travers la durée d'un plan, la photographie n'en présente qu'un infime instant et laisse l'action se déployer dans l'imaginaire du spectateur. Cadrage, composition, narration et forme (ou esthétique) sont autant de champs investis par les directeurs de la photographie et travaillés par les photographes soucieux de revêtir leurs images d'une ambiance cinématographique.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":101,"bookId":"book-052594aaf13d95f57c1c"},{"source_id":"scholarvox:88921977","title":"Le récit cinématographique","authors":["Gaudreault, André","Jost, François"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200614492","9782200618940"],"description":"Rédigé par deux pionniers de la narratologie du cinéma, Le Récit cinématographique est devenu, depuis sa première édition en 1990, un classique reconnu pour sa clarté.Véritable manuel d'introduction, mais aussi ouvrage de synthèse particulièrement précieux, il se destine aux enseignants et aux étudiants en cinéma et en communication, ainsi qu'à tous ceux qui veulent comprendre les concepts et les mécanismes du récit : la narration, l'espace, la temporalité et le point de vue. À l'occasion de cette troisième édition revue et augmentée, les références cinématographiques ont été actualisées, l'étude du récit a été étendue aux séries télévisées et des analyses de séquences de films et de séries ont été ajoutées pour illustrer l'usage que l'on peut faire des concepts.« […] rarement on aura vu autant de clarté et de concision dans un ouvrage traitant de narratologie et de cinéma. […] Parce qu'on ne se lasse pas d'un discours conjuguant limpidité et intelligence et parce qu'un bon ouvrage de synthèse manquait cruellement aux écrits sur la narratologie, voilà un petit essai auquel on reviendra souvent » (Marcel Jean, directeur de la Cinémathèque québécoise).","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":102,"bookId":"book-bd468404c8281ce96638"},{"source_id":"openedition:puv--110","title":"Le Temps d'une pensée","authors":["Marie-Claire Ropars-Wuilleumier"],"publisher":"Presses universitaires de Vincennes","platform":"openedition","isbns":["9782842922290","9782842929503"],"description":"Ces études rassemblées par Sophie Charlin portent sur des objets très divers (textes littéraires ou théoriques, films, photographies, tableaux) et mettent en lumière la réflexion menée au cours de ces trente années par Marie-Claire Ropars.\n\n\tSont explorés les rapports entre littérature et cinéma, et surtout la question de l’image présentée sous un double aspect, dans la littérature et dans les arts visuels, afin d’en mettre en lumière les paradoxes. Plus largement, on voit se construire la notion « d’esthétique plurielle », à la fois comme méthode d’approche des arts, par croisements et comparaisons, mais aussi comme définition d’une pluralité inhérente aux œuvres. Analyses très précises d’œuvres littéraires (Simon, Robbe-Grillet, Perec), picturales ou cinématographiques (Godard, Bresson, Welles) alternant avec des passages plus synthétiques et théoriques (mise en dialogue d’hypothèses avec celles de Deleuze, Blanchot, Eisenstein et Derrida).","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":103,"bookId":"book-7d1fc05dca4baf3a4ac5"},{"source_id":"scholarvox:88921578","title":"Le vocabulaire du cinéma","authors":["Journot, Marie-Thérèse"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200625405","9782200626778"],"description":"Outil indispensable pour l'étudiant en cinéma et audiovisuel ou le cinéphile, ce lexique définit près de 600 termes clés du cinéma employés par les spécialistes dans différents domaines. Les entrées sont illustrées d'exemples de films puisés dans l'histoire du 7e art et accompagnées de termes corrélatifs afin de permettre au lecteur de compléter ses connaissances. Cette 5e édition actualisée propose une trentaine de nouveaux articles, portant notamment sur le récit et le scénario.De la description du film aux notions théoriques de base en esthétique et narratologie, sans oublier la technique, les genres et les grands courants cinématographiques, découvrez tout le vocabulaire du cinéma.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":104,"bookId":"book-f53d653b475757712825"},{"source_id":"scholarvox:88927266","title":"Les autres arts dans l'art du cinéma","authors":["Cohen, Alain J.-J.","Sipère, Dominique"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753503885","9782753526907"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":105,"bookId":"book-7167927742fb96aa5d48"},{"source_id":"scholarvox:88926241","title":"Les formes brèves audiovisuelles : Des interludes aux productions web","authors":["Perineau, Sylvie"],"publisher":"CNRS éditions","platform":"scholarvox","isbns":["9782271072016","9782271130105"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":106,"bookId":"book-3c4287eca9631b944158"},{"source_id":"scholarvox:88927269","title":"Les images de l’eau : Dans le cinéma français des années 20","authors":["Thouvenel, Éric"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753509993","9782753561748"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":107,"bookId":"book-e37006e63361b3cfed29"},{"source_id":"openedition:septentrion--110635","title":"Les images et les mots","authors":[],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757407707","9782757427682"],"description":"Il y a aujourd’hui une crise de la description des images du cinéma, si l’on en croit une déclaration de Jean-Luc Godard pour qui les cinéphiles devraient s’inspirer du quotidien de sport L’Équipe : « Dans le compte-rendu que je lis, je retrouve vraiment ce qui s’est passé la veille », dans la mesure où les journalistes sportifs décrivent toujours finement les gestes et les actions qu’ils ont vus auparavant au stade.\n\tL’ironie du propos doit nous conduire à dépasser la plainte qui l’enveloppe, et à examiner dans le détail les manières dont la fonction descriptive se développe devant un film ou une séquence filmique : pour l’analyste, le théoricien des images, l’historien du cinéma, le philosophe cinéphile. Dans une époque où le discours sur le cinéma est confronté à d’importantes mutations (critique frontale et indifférenciée de la circulation des images, profusion des commentaires via les blogs internet), cet ouvrage répond à la nécessité de penser les protocoles contemporains de la description filmique. L’idée est de faire appel à des spécialistes de l’image pour apprécier avec eux comment s’est construite leur pensée du cinéma depuis une pluralité d’opérations descriptives. L’articulation entre l’objet et la méthode de description est constamment interrogée, à travers des contributions sur des réalisateurs très variés (de Hitchcock à Pasolini, d’Orson Welles à Gus Van Sant) et des objets filmiques spécifiques : fictions, remploi d’images, gestuelle des corps en action, dimension sonore du cinéma, etc. pour défendre une pratique descriptive toujours singulière et jamais définitive.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":108,"bookId":"book-44190185dd3ee73ae348"},{"source_id":"scholarvox:41001310","title":"Les paysages du cinéma","authors":["Mottet, Jean"],"publisher":"Editions Champ Vallon","platform":"scholarvox","isbns":["9782876732797","9791026706915"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":109,"bookId":"book-195c8507633a6fb3c3bd"},{"source_id":"openedition:pupo--7680","title":"Les récits visuels de soi","authors":["Magali Uhl"],"publisher":"Presses universitaires de Paris Nanterre","platform":"openedition","isbns":["9782840162285","9782840164128"],"description":"Comment aujourd’hui, à l’ère des pratiques photographiques et filmiques amateurs, de la mobilité et de l’importance croissante du numérique, s’écrit visuellement l’intimité ? Selon quels procédés, découpages, montages opèrent les artistes actuels pour tracer les contours du soi contemporain et quels types de narration en proposent-ils ?\n\tQu’elle soit la conséquence d’un échec amoureux ou d’une quête familiale, d’un apprentissage de la différence ou du ressenti de la perte, des stigmates de l’exil ou de l’épreuve de l’Histoire, l’écriture visuelle de soi n’est pas qu’une question adressée au sujet et à son idiosyncrasie, elle entretient aussi des liens ténus avec la mémoire et l’expérience collectives.\n\tInvitant à voyager dans ces mises en récit de soi, le présent ouvrage souhaite documenter ces nouvelles expérimentations artistiques en dialogue avec les pratiques du quotidien. Il interroge le potentiel de refiguration des procédés mis en œuvre, la capacité des sujets à les mobiliser pour produire une expérience esthétique, laisser émerger un vécu, mais aussi visiter une mémoire ou la questionner, raconter une histoire ou seulement l’ébaucher, ouvrir aussi à d’autres virtualités.\n\tEntre histoire des représentations et histoire matérielle, études littéraire, visuelles, plastiques et études culturelles, les auteur(e)s ayant contribué à cet ouvrage proposent ainsi différentes perspectives sur l’écriture visuelle de soi et sur ses procédés.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":110,"bookId":"book-f344a4a15fc67c6ad094"},{"source_id":"scholarvox:88925419","title":"Les écarts du cinéma","authors":["Rancière, Jacques"],"publisher":"La fabrique éditions","platform":"scholarvox","isbns":["9782358720229","9782358721301"],"description":"Le cinéma n'existe peut-être que sous la forme d'un système d'écarts entre des choses qui portent le même nom sans être membres d'un même corps. C'est le lieu matériel où l'on s'émeut au spectacle des ombres. C'est aussi le nom d'un art constitué comme tel par la passion cinéphilique qui a brouillé les frontières de l'art et du divertissement. Ce fut, un temps, l'utopie d'une écriture du mouvement, unissant le travail, l'art et la vie collective. C'est parfois encore le rêve toujours déçu d'une langue des images. Jacques Rancière étudie quelques formes exemplaires de ces écarts: le cinéma prend à la littérature ses fictions en effaçant ses images et sa philosophie. Il rejette le théâtre au prix d'en accomplir le rêve. Il règle le passage de l'émotion des histoires au pur plaisir de la performance ou alourdit les corps pour nous montrer la pensée à l'aeuvre. Il expose en même temps la capacité politique de tous et son propre pouvoir d'en transformer les manifestations en feux d'artifice ou en formes qui se dissipent comme des cercles à la surface de l'eau.--","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":111,"bookId":"book-42ca93dbeb96607bc7c0"},{"source_id":"scholarvox:88927271","title":"Les œuvres d'art dans le cinéma de fiction","authors":["Mouëllic, Gilles","Fiant, Antony","Frangne, Pierre-Henry"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753532618","9782753561540"],"description":"\"Comment penser un film de fiction à partir des oeuvres d'art qui s'y trouvent sous la forme d'objet, de représentation, de projet, de performance ou d'événement? À l'inverse, comment penser les oeuvres et les arts non filmiques à partir du cinéma qui les met en scène, en images et en récit? C'est à ces deux questions reliées circulairement qu'est consacré cet ouvrage collectif où dialoguent historiens, théoriciens, critiques et esthéticiens du cinéma. Dans ce dialogue ouvert et pluridisciplinaire, le lecteur cernera d'abord les principales opérations, fonctions, modalités et portées de ce jeu baroque souvent fascinant d'emboîtements et de citations par lequel le film de fiction se laisse nourrir, creuser, perturber, altérer, hanter par d'autres oeuvres d'art que les oeuvres cinématographiques elles-mêmes. Il verra ensuite, et en retour, comment les oeuvres littéraires, plastiques, musicales, chorégraphiques, architecturales, théâtrales que les fictions filmiques utilisent, se laissent éclairer par la lumière propre du cinéma.\"--P. [4] of cover.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":112,"bookId":"book-5ed712dc38e2b54bc806"},{"source_id":"scholarvox:88927272","title":"Lettres de cinéma : De la missive au film-lettre","authors":["Cloarec, Nicole"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753505308","9782753526938"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":113,"bookId":"book-f0c688444e24d40fd30d"},{"source_id":"openedition:edizionikaplan--947","title":"L’occhio sensibile","authors":["Silvio Alovisio"],"publisher":"Edizioni Kaplan","platform":"openedition","isbns":["9788889908709","9788899559298"],"description":"Tra la fine dell’Ottocento e i primi decenni del Novecento il sistema dei media e il sapere  neuroscientifico vivono un comune destino di epocale modernizzazione: da un lato, il cinema si afferma rapidamente come la più popolare esperienza comunicativa e spettacolare dell’Occidente, dall’altro gli sviluppi della ricerca neurologica, psicologica e psichiatrica  consolidano la conoscenza dei fenomeni percettivi e mentali. Anche in Italia, così come in Francia, in Germania e negli Stati Uniti, le scienze della mente si mostrano da subito  interessate a studiare il cinema e i suoi spettatori. Il nuovo medium è quindi posto al centro di una riflessione scientifica poliforme ma tutt’altro che occasionale: psicologi come Mario Ponzo, Agostino Gemelli, Sante De Sanctis e Cesare Musatti, neurologi come Giuseppe  D’Abundo e Liborio Lojacono, fisiologi come Carlo Foà e Mariano Luigi Patrizi, psichiatri come Giuseppe Vidoni, Guglielmo Mondio e Fabio Pennacchi, studiano gli aspetti percettivi ed  emozionali della ricezione spettatoriale, il ruolo assunto nella visione in sala dall’illusione di realtà, dalla memoria e dall’attenzione, i problematici effetti psichici e sociali prodotti dal cinema, ma anche le sue promettenti potenzialità pedagogiche.\n\tIl presente volume, corredato da un’antologia di testi d’epoca, si propone di offrire un contributo  lla conoscenza e allo studio di queste riflessioni della comunità scientifica italiana, maturate in un periodo decisivo non solo per la storia delle scienze psichiche e per la storia del cinema ma anche, e soprattutto, per la problematica costruzione della moderna soggettività novecentesca.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":114,"bookId":"book-737c1503ba8920cd8bc0"},{"source_id":"scholarvox:88927290","title":"L’ombre d’un doute : Le cinéma américain contemporain et ses trompe-l’œil","authors":["Ledoux, Aurélie"],"publisher":"Presses universitaires de Rennes","platform":"scholarvox","isbns":["9782753518186","9782753561656"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":115,"bookId":"book-72d86e81f05abbb1a51b"},{"source_id":"openedition:pupo--21622","title":"Muséoscopies","authors":[],"publisher":"Presses universitaires de Paris Nanterre","platform":"openedition","isbns":["9782840162810","9782840164234"],"description":"Architectures grandioses, expositions médiatisées à outrance et instituées en rituels saisonniers, le musée est aujourd’hui investi d’une attractivité touristique et d’une charge patrimoniale, politique, symbolique sans précédent. Ce qui s’y monnaye est-il cette « monnaie de l’absolu » dont André Malraux célébra l’universalité ? L’interrogation court tout au long de cet ouvrage qui choisit le prisme du cinéma de fiction pour revisiter le musée, dans ses missions et mythologies traditionnelles mais aussi dans ses coulisses et sa violence. Au final, les intrigues muséales tramées entre autres par Michael Curtiz, Tsai Ming-liang, Jean- Luc Godard, les frères Quay, Sanjay Gadhvi, Marco Bellocchio ou Charles Crichton sondent notre rapport fétichiste à l’œuvre d’art et notre regard sur le patrimoine. À travers des analyses subtiles et décapantes, muséologues, historiens de l’art et du cinéma nouent un dialogue qui atteste la puissance discursive de la fiction. Il en naît aussi une éclatante relance théorique sur les fonctions du musée, sur les valeurs qui s’y transmettent, s’y échangent, s’y révisent et s’y réinventent.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":116,"bookId":"book-4d14298e569831ddc262"},{"source_id":"openedition:ugaeditions--62017","title":"Nancynéma, le cinéma selon Jean-Luc Nancy","authors":[],"publisher":"UGA Éditions","platform":"openedition","isbns":["9782377475827","9782377476237"],"description":"Philosophe de l’expérience sensible, Jean-Luc Nancy a multiplié ses rencontres avec le cinéma, cet art surnuméraire à la diversité essentielle : en tant que cinéfile – tel qu’il le définit en regard d’une cinéphilie savante dont il serait le cœur secret –, en tant que penseur occasionnel mais « pénétrant », ou en tant qu’inventeur de concepts esthétiques – tels l’écoute, le toucher, l’évidence du film. Dans sa confidence du « plaisir immense, aussi sensuel qu’intellectuel » qu’il trouve à analyser des plans se dessine le nœud qui l’attache aux films et le spectateur à ses textes : une homothétie entre philosophie et cinéma – écriture du sensible, pensée en images, fulgurances poétiques trouant l’obscurité du sens. Cet ouvrage collectif inédit mobilise les plus éminents spécialistes pour envisager le cinéma selon Nancy – « l’émotion de sa motion ». Il met en perspective ses textes esthétiques, éthiques, politiques et ses compagnonnages créatifs, de Claire Denis à Phillip Warnell.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":117,"bookId":"book-3533bc7baaf69e87ab57"},{"source_id":"openedition:septentrion--46454","title":"Numérique et transesthétique","authors":[],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757403730","9782757421666"],"description":"Les innovations techniques ouvrent de nouveaux possibles qui doivent être actualisés par une critique des modes de représentation actuels. Cet ouvrage articule réflexion théorique et études de terrain autour de trois grandes thématiques : le devenir du film à l’heure de la numérisation, les pratiques artistiques et culturelles liées à l’internet, et l’imaginaire esthétique accompagnant ces dernières technologies.\n\tFace aux développements de la télévision délinéarisée et de l’internet, l’industrie cinématographique se régénère en capitalisant sur les superproductions, images en 3D et son aux sources démultipliées, offrant des sensations brutes proches des origines foraines du cinéma. La question aujourd’hui ne serait plus « qu’est-ce-que le cinéma ? » mais « qu’est-ce qu’un film ? » indissociable des pratiques actuelles brouillant les distinctions entre professionnels et amateurs. Émerge la figure de l’artisan, non plus image désuète, mais réponse aux dilemmes de l’artiste-auteur confiné dans les espaces muséaux distincts des productions industrielles transnationales adeptes de syncrétismes culturels.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":118,"bookId":"book-efdf2f7000740e9096fd"},{"source_id":"scholarvox:88947296","title":"On The Figure In General And The Body In Particular : Figurative Invention In Cinema","authors":["Fendt, Ted","Brenez, Nicole"],"publisher":"Anthem Press","platform":"scholarvox","isbns":["9781839987809","9781839987823"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":119,"bookId":"book-e1509fce2736a4fefab5"},{"source_id":"openedition:ugaeditions--34394","title":"Penser les formes filmiques contemporaines","authors":[],"publisher":"UGA Éditions","platform":"openedition","isbns":["9782377473830","9782377474103"],"description":"Comment penser les formes filmiques contemporaines dans un monde éminemment complexifié, à l’ère d’une mondialisation débridée, où la circulation des images n’a jamais été aussi massive et rapide ? C’est un véritable défi pour l’analyste des images, qui peut lui-même se dire contemporain à la seule condition d’être « celui qui perçoit l’obscurité de son temps comme une affaire qui le regarde et n’a de cesse de l’interpeller », selon le philosophe Giorgio Agamben. Articulée autour de quatre hypothèses de travail – Temporalités contrariées ; Mémoires stratifiées ; Espaces reconfigurés ; Mondes partagés – la réflexion collective menée ici interroge à la fois la manière dont les formes filmiques contemporaines pensent et analysent le monde, et comment elles suscitent en retour l’invention de nouveaux gestes, méthodes, postures, techniques, stratégies et outils analytiques afin de continuer à penser avec exigence les images et les œuvres d’aujourd’hui.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":120,"bookId":"book-b927751a644d8b159758"},{"source_id":"scholarvox:88969572","title":"Pour un cinéma contemporain soustractif","authors":["Fiant, Antony"],"publisher":"Presses Universitaires de Vincennes","platform":"scholarvox","isbns":["9782842924065","9782842926939"],"description":"\"Depuis le début du XXIe siècle, on observe l'apparition régulière de films minimalistes manifestant une réticence marquée envers le scénario, le récit, la parole, la musique et la psychologie. Qu'ils relèvent de la fiction, du documentaire, ou des deux à la fois, les films de quinze cinéastes du monde entier (Lisandro Alonso, Wang Bing, Alain Cavalier, Pedro Costa, Darejan Omirbaev, Béla Tarr, entre autres) sont ici analysés d'un point de vue esthétique et dramaturgique pour mieux mettre en évidence un geste soustractif. Moins d'histoire, moins de dialogues, moins de décors, ces caractéristiques manifestent une belle foi en l'art du cinéma et en sa capacité de suggestion.\"--P. [4] of cover.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":121,"bookId":"book-a0d1fdb6daf648e6202f"},{"source_id":"scholarvox:88969523","title":"Pulsions dansantes du cinéma expérimental (1920-1970)","authors":["Janicas, Bárbara"],"publisher":"Presses Universitaires de Vincennes","platform":"scholarvox","isbns":["9782379245121","9782379245145"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":122,"bookId":"book-1e361e35b804ad61e63c"},{"source_id":"scholarvox:88921596","title":"Qu'est-ce qu'un bon film ?","authors":["Jullier, Laurent"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200629878","9782200631116"],"description":"– J'ai adoré.– Tu es fou ? C'était mauvais.Au cinéma, nous n'avons pas tous les mêmes goûts. Il existe quantité de raisons de s'enthousiasmer pour un film (ou de bâiller devant lui), et ce livre en fait le tour. Il ne tranche pas. Quels que soient mes goûts et ceux de mon voisin, je n'ai pas à me sentir inférieur ni supérieur à lui. Même s'il fait la moue quand je lui dis quel est mon film préféré. D'ailleurs la recette du bon film n'existe pas, sinon les réalisateurs l'appliqueraient depuis longtemps. Tout le monde fait de son mieux, de chaque côté de l'écran. Ce n'est pas facile. On ne sait pas toujours dire à l'avance quelles qualités un film doit posséder pour nous plaire. Et en sortant de la séance, on ne sait pas toujours quoi dire. Qu'est-ce qu'un bon film ? dédramatise la question. Acceptons nos différences.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":123,"bookId":"book-73e8517ff132c1397179"},{"source_id":"openedition:pus--44198","title":"Questions de cinéma et pratique de l’analyse de film","authors":["Jean-Pierre Esquenazi"],"publisher":"Presses universitaires de Strasbourg","platform":"openedition","isbns":["9791034400386","9791034403455"],"description":"Chaque film à sa manière nous apprend le cinéma : les questions que le réalisateur et son équipe se sont posées affleurent dans le récit, elles émergent de l’enchaînement des images et des sons. Pour qui veut bien s’y montrer attentif, un film peut devenir, non pas un manuel, mais un guide. Cet ouvrage suit à la trace cinq questions posées par cinq films ou ensembles de films, des questions que ces œuvres se posent d’abord à elles-mêmes. La mise en scène en est profondément marquée : la pratique de l’analyse de film devient dans cette perspective – au-delà du plaisir que l’on peut prendre à redécouvrir, explorer, ausculter parfois un film qu’on a aimé – un instrument de réflexion sur le cinéma, sur des problèmes propres à l’art cinématographique.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Analyses de films"]},"reason":"Methodes et exercices d analyse de films; revue critique avec analyses de films identifies.","index":124,"bookId":"book-1500e2b03d1295adf591"},{"source_id":"openedition:edizionikaplan--227","title":"Racconti di corpi","authors":["Luca Malavasi"],"publisher":"Edizioni Kaplan","platform":"openedition","isbns":["9788889908419","9788889908884"],"description":"I film sono straordinari dispositivi emozionali: ci attraggono e ci coinvolgono, ci toccano e ci fanno sperimentare passioni spesso laceranti, ci muovono dentro e al fianco dei personaggi sullo schermo, e ce ne fanno condividere la sorte e i sentimenti nella forma di un’esperienza di partecipazione che si prolunga ben oltre l’ultimo fotogramma.\n\n\tAll’incrocio tra semiotica e fenomenologia, il libro esplora le complesse dinamiche cognitive ed emotive al centro dell’esperienza cinematografica, rinnovando il dibattito teorico attorno a temi di grande attualità, come quelli delle passioni e del corpo.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":125,"bookId":"book-9165965934d84b9029f5"},{"source_id":"scholarvox:88952946","title":"Roland Barthes : en sortant du cinéma","authors":["Collectif"],"publisher":"Editions Hermann","platform":"scholarvox","isbns":["9782705697525","9791037023254"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":126,"bookId":"book-ccbb75407ba508f25cc5"},{"source_id":"openedition:edizionikaplan--866","title":"Rudolf Arnheim. I baffi di Charlot","authors":["Rudolf Arnheim"],"publisher":"Edizioni Kaplan","platform":"openedition","isbns":["9788889908372","9788899559281"],"description":"Nel cuore degli anni Trenta Rudolf Arnheim fu tra i principali animatori del dibattito italiano sul cinema. Le tracce di quella fugace ma intensa stagione, segnata da una rocambolesca fuga a causa delle leggi razziali, rischiavano di andare perdute. Questo volume riporta alla luce un consistente corpus di articoli e saggi apparsi sulle più importanti riviste specializzate dell’epoca, a testimonianza del signifi cativo ruolo che Arnheim ebbe nel panorama culturale del nostro paese e dell’importanza che la sua parabola italiana ricoprì nella maturazione del successivo lavoro. Ad emergere è un volto inedito di Arnheim, acuto osservatore della produzione cinematografi ca internazionale e ponderato divulgatore degli aspetti psicologici e tecnologici dell’arte delle immagini in movimento. Una voce autonoma, originale e diretta che ancora oggi può parlare agli studiosi e agli appassionati di cinema.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":127,"bookId":"book-8ce39daf30f75fcc2958"},{"source_id":"openedition:pupo--3482","title":"Rêve et cinéma","authors":[],"publisher":"Presses universitaires de Paris Nanterre","platform":"openedition","isbns":["9782821850910","9782840161035"],"description":"Du dispositif clinique de Léonce Perret dans Les Mystères des Roches de Kador (1913) aux labyrinthes lynchiens d’Inland Empire (2006), de secrètes résonances relient des films que tout, de leur régime d’images à leur forme de récit ou à leur inscription culturelle, contribue à éloigner. Ils se nourrissent pourtant d’une même énergie créatrice en puisant, selon des modalités et un travail très différents, aux puissantes fantasmagories du rêve.\n\tOn pourrait croire que l’essentiel a été dit, et bien dit, des liens rhétoriques et poétiques que le cinéma entretient avec l’onirisme et ses territoires mitoyens – fantasmes, hallucinations, images obsédantes, effets hypnotiques -, alors même que des approches nouvelles font retour aujourd’hui – notamment sur le freudisme – pour inventer et proposer des voies et des concepts inédits à la mesure d’un champ créatif et théorique en constante mutation.\n\tAutour du prisme du rêve, vu comme trompe-l’œil et simulacre ou comme expérience poétique et figurale, c’est donc l’horizon le plus avancé des études filmiques qui se dessine ici. L’entretien final de Marie Martin et Raymond Bellour inscrit ce recueil dans la perspective qui est la sienne : questionner le rêve « aux fins d’une histoire de la théorie du cinéma », histoire inséparable de celle de la création contemporaine, sur fond d’orage, de métamorphoses et d’inquiétante étrangeté…","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":128,"bookId":"book-bdec07ae668ec1cc455e"},{"source_id":"scholarvox:88921572","title":"Rêves et cauchemars au cinéma","authors":["Scheinfegel, Maxime"],"publisher":"Armand Colin","platform":"scholarvox","isbns":["9782200276157","9782200281786"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":129,"bookId":"book-8bb30df7281bc95f6d77"},{"source_id":"gale:9780028661001","title":"Schirmer Encyclopedia of Film, 4v","authors":["Barry Keith Grant"],"publisher":"Schirmer Reference","platform":"gale","isbns":["9780028657912","9780028661001"],"description":"This reference provides a comprehensive and accessible introduction to film and film studies, covering such aspects as production, national traditions, studios, genres, critical theory and film history.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":130,"bookId":"book-8bfbecb2d7e733bbf76e"},{"source_id":"openedition:septentrion--180526","title":"Silence(s) dans le cinéma contemporain","authors":["Louis Daubresse"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757439531","9782757439777"],"description":"Comment le silence agit-il au cinéma ? Qu’est-ce qui permet d’identifier ce phénomène ? Implique-t-il la disparition intégrale de la matière sonore ou seulement sa minimalisation à l’intérieur d’un film ? Son intervention, ponctuelle ou durable, tend à engager une raréfaction, voire une suppression, des paroles et de la musique, mais pas forcément de tout bruit. Des lieux particulièrement silencieux, ainsi que le mutisme ou la surdité d’un personnage, sont également propices à l’instauration de telles situations audiovisuelles.À travers une approche généalogique et herméneutique, l’ouvrage analyse la présence du silence dans le cinéma contemporain sur le double principe d’héritages figuratifs et de ruptures discursives. Il s’appuie sur un corpus de films réalisés entre autres par Robert Bresson, Marguerite Duras, Andrei Tarkovski, Theo Angelopoulos, Tsaï Ming-liang, Béla Tarr, Pedro Costa ou Sharunas Bartas. Au-delà des considérations esthétiques, le livre interroge aussi les valeurs anthropologiques, morales, sociales et/ou politiques qui se glissent derrière ces manifestations concrètes du silence. Celui-ci nous invite, tant sur le plan éthique que sensible, à repenser notre rapport fondamental au monde.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Musique / Son"]},"reason":"Silence comme phenomene sonore filmique : paroles, musique, bruit et rarefaction.","index":131,"bookId":"book-258fc026a130a5bdd59d"},{"source_id":"scholarvox:88867733","title":"Spatialités littéraires et filmiques francophones : Nouvelles perspectives","authors":["Naudillon, Françoise","Diouf, Mbaye","Sidaoui, Sihem"],"publisher":"Mémoire d'encrier","platform":"scholarvox","isbns":["9782897125448","9782897125462"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":132,"bookId":"book-768dcf413c8186a35f6b"},{"source_id":"scholarvox:88903244","title":"Spectres du cinéma 2 : Revue de cinéma","authors":["Torrigiani, Pietro","Claës, Balthazar","Jerzy P."],"publisher":"LettMotif","platform":"scholarvox","isbns":["9782367160269","9782919070817"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Analyses de films"]},"reason":"Methodes et exercices d analyse de films; revue critique avec analyses de films identifies.","index":133,"bookId":"book-651a424d95b94e08922a"},{"source_id":"scholarvox:88949406","title":"The Anthem Handbook of Screen Theory","authors":["Vaughan, Hunter","Conley, Tom"],"publisher":"Anthem Press","platform":"scholarvox","isbns":["9781783088232","9781783088249"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":134,"bookId":"book-2b4c98143d988d721255"},{"source_id":"scholarvox:88948966","title":"The City on Screen : Modern Strangers of Cinematic Istanbul","authors":["Demir, Sertaç Timur"],"publisher":"Vernon Press","platform":"scholarvox","isbns":["9781648897870","9781648898013"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéma et société"]},"reason":"Biopouvoir, corps social, frontieres, savants representes, publics, precarite, ville, migrations ou critique amateur : angle social principal.","index":135,"bookId":"book-73d786661740350b8866"},{"source_id":"scholarvox:88874992","title":"The SAGE Handbook of Film Studies Ed. 1","authors":["Donald, James"],"publisher":"SAGE Publications","platform":"scholarvox","isbns":["9780761943266","9781446206829"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":136,"bookId":"book-c85eec616d02b979645b"},{"source_id":"scholarvox:88969487","title":"Tourner le dos - Sur l'envers du personnage au cinéma","authors":["Thomas, Benjamin"],"publisher":"Presses Universitaires de Vincennes","platform":"scholarvox","isbns":["9782842923600","9782842926618"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":137,"bookId":"book-e7c0281fa5b4d5267a3a"},{"source_id":"scholarvox:88824750","title":"Tout ce que vous avez toujours voulu savoir sur Lacan sans jamais oser le demander à Hitchcock","authors":["Zizek, Slavoj"],"publisher":"Capricci Editions","platform":"scholarvox","isbns":["9782918040101","9791023900453"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":138,"bookId":"book-d7b3a4b179abb09c97c6"},{"source_id":"scholarvox:88943131","title":"Un cinéma en mouvement : Portabilité des appareils et formes filmiques","authors":["Bégin, Richard","Carrier-Lafleur, Thomas","Mouëllic, Gilles"],"publisher":"Presses de l'Université de Montréal PUM","platform":"scholarvox","isbns":["9782760646544","9782760646551"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":139,"bookId":"book-9124e94cf2983e9559ae"},{"source_id":"scholarvox:88969524","title":"Un film peut en cacher un autre","authors":["Scheinfeigel, Maxime"],"publisher":"Presses Universitaires de Vincennes","platform":"scholarvox","isbns":["9782842925710","9782842925734"],"description":"\"Ce livre analyse des images réunies selon des associations libres, que provoque la vision de certains films. Au-delà de l'observation et de la mémoire d'images déjà vues autrement et ailleurs, le spectateur devenu analyste repère tout un réseau de figures, mises au travail par le cinéma et qui forment la trame de l'ouvrage: le palimpseste, l'absence, le vide. Orson Welles et Béla Tarr, Leos Carax, Dziga Vertov et Raul Ruiz, U les frères Larrieu et François Leterrier, Nuri Bilge Ceylan, Olivier Assayas, Jonathan Glazer et Lasse Hallstrônn, Billy Wilder, Jean-Luc Godard et André Téchiné ont tissé ces figures qui se saisissent comme des empreintes, se laissent décrypter comme des pensées de rêve.\"--Page 4 of cover.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":140,"bookId":"book-f714601b16cf59dc8c2d"},{"source_id":"openedition:edizionikaplan--620","title":"Videoestetiche dell'emergenza","authors":["Elena Marcheschi"],"publisher":"Edizioni Kaplan","platform":"openedition","isbns":["9788899559007","9788899559151"],"description":"Crisi, emergenze, catastrofi. I fatti dell’11 settembre 2001 hanno inaugurato un millennio in cui sembrano intensificarsi guerre e conflitti, pandemie, emergenze ecologiche, e il nuovo disordine mondiale genera impoverimento e disuguaglianze, esaspera paure personali e collettive. Con un approccio interdisciplinare che non trascura cenni storici, antropologici e sociologici, il libro propone l’analisi di un ampio ventaglio di opere realizzate da artisti di vari paesi del mondo nell’ultimo quindicennio su emergenze e crisi planetarie. Una produzione “deterritorializzata”, in cui la pratica e\n\tl’etica del cinema del reale sono recuperate in modo innovativo, tra le estetiche incerte degli smartphone e l’eredità del cinema sperimentale e della videoarte in dialogo col digitale.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":141,"bookId":"book-824128c6b6d0243d1d46"},{"source_id":"scholarvox:88932679","title":"Vocation du cinéma (suivi de « Charlot ») [édition intégrale revue et mise à jour]","authors":["Faure, Élie"],"publisher":"Ink book","platform":"scholarvox","isbns":["9791023204292"],"description":"","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":142,"bookId":"book-de97fbf4ad65226e7e82"},{"source_id":"openedition:septentrion--11245","title":"Voyages et exils au cinéma","authors":[],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757414873","9782757417676"],"description":"Voyages et exils au cinéma, rencontres de l'altérité s’intéresse aux phénomènes d’hybridation entre cultures tels qu’ils se traduisent à l’écran, sans restriction géographique (cinémas américain, italien, africain, libanais, indien, taïwanais, japonais etc.). Si le voyage et l’exil des cinéastes sont sources de transferts culturels et esthétiques, le thème du voyage et de l’exil représenté au cinéma questionne la notion d’altérité en proposant une vision diversifiée de la rencontre entre autochtones et nouveaux arrivants.\n\tDans un monde globalisé, mais qui continue de s’interroger à la fois sur la mixité culturelle et le sens de la nation, le cinéma reflète ainsi les cultures plurielles dans leur richesse et leur vivacité, mais aussi les replis communautaires, les phénomènes d’imprégnation et bien entendu de domination culturelle. La caméra se désigne alors comme acteur, témoin et exégète de ces processus qui, s’ils ont une longue histoire et se développent tout au long du xxe siècle, culminent dans notre temps présent.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéma et société"]},"reason":"Biopouvoir, corps social, frontieres, savants representes, publics, precarite, ville, migrations ou critique amateur : angle social principal.","index":143,"bookId":"book-e8d00103046b5eb5a578"},{"source_id":"openedition:iblpan--2291","title":"W stronę wirtualności","authors":["Matylda Szewczyk"],"publisher":"Instytut Badań Literackich Polskiej Akademii Nauk","platform":"openedition","isbns":["9788364703416","9788367637350"],"description":"Wyprawę kina \"w stronę wirtualności\" - w stronę nowych sposobów jego tworzenia, rozumienia i egzystencji w czasach przemian technologii medialnych - śledzić będziemy przede wszystkim przez pryzmat wybranych praktyk artystycznych trojga twórców: Petera Greenawaya (wielokrotnie powtarzającego tezę o \"śmierci\" tradycyjnego kina i o narodzinach nowego sposobów obrazowania), Lynn Hershman Leeson (amerykańskiej artystki \"kina rozszerzonego\") i Mike’a Figgisa, który w swoich autotematycznych filmach snuł refleksję o różnych rodzajach obrazów filmowych i o kinie epoki cyfrowej.\n\n\tDyskusję nad kinem wprowadzimy także na szersze obszary refleksji kulturowej. Pytania o \"wirtualizację\" kultury wymagać będą próby zdefiniowania pojęcia \"wirtualności\", prześledzenia jego wędrówki przez różne poziomy kulturowych dyskursów i odniesienia go do analizowanych prac. W stronę wirtualności... to książka o kinie (o jego twórcach, dziełach i bohaterach) zanurzonym w technologicznych, filozoficznych, naukowych i, najszerzej, kulturowych przemianach współczesności.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":144,"bookId":"book-cb2a28c12a102c018276"},{"source_id":"openedition:septentrion--6753","title":"Y a t-il un cinéma d'auteur ?","authors":["Michel Serceau"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757407738","9782757414316"],"description":"La vulgarisation de la notion d'auteur de film, tant du côté de la réception que de la production, fait écran à une question que la critique, héritière zélée de la Politique des auteurs mise en œuvre par les Cahiers du cinéma de jadis, ne pose plus, celle des critères qui permettraient de distinguer, de même que l'on distingue les écrivains des écrivants, les grands cinéastes des réalisateurs et des tâcherons. Ceci ne suffit pas à cela. Les critères d'appréciation étant devenus plus culturalistes qu’esthétiques, ou alors esthétisants, il n’est pas certains en bref que ceux que l’on présente comme des auteurs et les auteurs eux-mêmes soient de grands cinéastes. On ne prend guère en compte la façon dont le film fait sens au-delà de l’information, du discours, du message. Il ne suffit pas d’effets de sens, il faut que le spectateur soit mis en position de participer et même de construire du sens. Des classiques aux modernes, le cinéma a certes considérablement évolué : de nouveaux genres sont apparus, le cinéma documentaire a effectué des avancées et des mues essentielles, on n’est pas auteur aujourd’hui comme on l’était à l’époque des studios. Mais suffit-il d’être auteur ? Les critères sont plus que jamais nécessaires pour distinguer ceux des cinéastes qui sont, au même titre que les grands écrivains et artistes, des créateurs.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":145,"bookId":"book-18ccdda988f2a8873caa"},{"source_id":"openedition:pressesmines--2251","title":"« Moi je lui donne 5/5 »","authors":["Dominique Pasquier","Valérie Beaudouin","Tomas Legon"],"publisher":"Presses des Mines","platform":"openedition","isbns":["9782356711410","9782356714527"],"description":"Partout sur le web, les internautes sont incités à donner leur avis et à s’exprimer librement. Les opinions des consommateurs se sont-elles fait une place face au pouvoir des élites expertes ? Peut-on parler d’un empowerment ? Les auteurs ont mené une enquête fouillée sur un site qui héberge de très nombreuses critiques de films émanant de cinéphiles ou d’amateurs ordinaires et ils remettent en cause nombre d’idées reçues. On découvrira des critiques amateurs passionnés et prêts à en découdre avec les jugements des experts ; on verra combien ce monde d’auteurs, si hétérogène, s’avère hiérarchisé ; on comprendra que, de manière paradoxale, plus un amateur écrit, plus il reprend les normes de la critique professionnelle. L’enquête regarde aussi l’envers des pratiques amateurs : ceux-ci savent-ils en effet que leurs critiques sont bien moins influentes que les bandes-annonces des films et qu’elles intéressent fort peu les professionnels du site qui fondent leur modèle économique sur les notes et non sur les textes ? Cet ouvrage invite ainsi à reposer la question de la place de la créativité amateur dans le monde de l’internet.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Cinéma et société"]},"reason":"Biopouvoir, corps social, frontieres, savants representes, publics, precarite, ville, migrations ou critique amateur : angle social principal.","index":146,"bookId":"book-0126024177a67e4c64f6"},{"source_id":"openedition:septentrion--130296","title":"Écrans variables","authors":["Hugo Orts"],"publisher":"Presses universitaires du Septentrion","platform":"openedition","isbns":["9782757436806","9782757437049"],"description":"Souvent ignoré, le format d’image constitue pourtant un élément de mise en scène participant pleinement à la réception qui est faite d’un film. Partant de ce principe et à travers des analyses précises de séquences allant du cinéma muet jusqu’à nos jours, cet ouvrage interroge les possibilités offertes par l’acceptation d’un paradigme dans lequel le ratio d’image n’est plus contraint d’être unique à l’échelle du film, abordant aussi bien les variations ostensibles de formats que l’emploi plus subtil de certaines de leurs qualités propres. Afin de redécouvrir par un biais nouveau les déterminations imposées par le cadre sur ce qu’il contient – le champ –, mais aussi sur ce qu’il exclut – le hors-champ –, le format d’image est ici considéré comme un procédé esthétique à part entière, vecteur de sens et de sensations à même de nous éclairer sur notre expérience de spectateur.","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Esthétique"]},"reason":"Formes, figures, styles, espace, corps, couleur, perception sensible et relations entre arts; analyse formelle plutot que manuel technique.","index":147,"bookId":"book-c14c322052634348f418"},{"source_id":"peterlang:1052140","title":"Порядок «xaoca» – «xaoc» порядка- L’ordre du chaos – le chaos de l’ordre","authors":[],"publisher":"Peter Lang","platform":"peterlang","isbns":["9783035100242"],"description":"Порядок и хаос видит ученый в исследуемом материале и в истории своей дисциплины. Порядок порою оказывается иллюзорным, а хаос – плодотворным и стимулирующим. Тематическая и методологическая «анархичность» данного сборника соответству ет открытой творческой личности Леонида Геллера. Статьи, представлен ные в книге, затрагивают историю русской и польской литературы, поэтику, теорию поэтическог о языка и теорию литературы, вопросы теории и истории кино. Читатель найдет здесь работы о «Риме» Гоголя и «Лолите» Набокова, о киноавангар де, о стихах Пушкина и Бродского, о прозе Гайдара и Каверина, о похвальной речи Эйлеру и о проделках Тиля","from":[["Art / Culture","Cinéma / Audiovisuel","Esthétique / Théorie"]],"destination":{"family":"Art / Culture","subcategory":"Cinéma / Audiovisuel","details":["Théorie"]},"reason":"Concepts, ontologie, philosophie, recit, semiologie, reception et methodes generales; syntheses mixtes classees ici sans duplication esthetique.","index":148,"bookId":"book-67810c4bcf4179756271"}];
